window.POEM_DB=window.POEM_DB||{};POEM_DB["song_027"]={"n":"陈著","dyn":"宋","poems":[{"t":"乙酉正月二十日游慈云三首 其一","f":"七言绝句","c":["数曲清溪山抱回，青山高处醉筵开。","忽然鼓笛太平调，便是洞庭闻乐来。"]},{"t":"丁丑五月六日醵饮茂林偶成","f":"七言绝句","c":["夹路松杉护午阴，南风吹透树中心。","一声婆饼焦何处，妙法莲花此妙音。"]},{"t":"九月一日戴时可酒边 其一","f":"七言绝句","c":["老夫不是不知时，黄菊芙蓉正要诗。","谁信多魔儿女病，催租风雨又攒眉。"]},{"t":"九月一日戴时可酒边 其二","f":"七言绝句","c":["不知今日是何时，只管飞毫醉梦诗。","天地本来宽著我，可曾寒饿一低眉。"]},{"t":"儿童以石舟戏于池","f":"七言绝句","c":["浮生已付四宜休，老病光阴黄叶秋。","底用燕嬉居画舫，何妨飘忽悟虚舟。"]},{"t":"八字桥","f":"七言绝句","c":["二灵山下湖光润，八字桥头河水分。","此是江东最佳处，近来风景不堪闻。"]},{"t":"又次韵二首 其二","f":"七言绝句","c":["赋诗谁复待沈香，澒洞乾坤走险忙。","寂寂春光伤感处，瘦来不是沈东阳。"]},{"t":"又次韵二首 其一","f":"七言绝句","c":["犹记年时花下醉，老怀今已不成春。","深黄浅紫知何在，留得残莺啼向人。"]},{"t":"又次韵帅初诸前七首 其七","f":"七言绝句","c":["君是能诗犹可及，及君不可是吾年。","有怀伐木相求意，但诵投瓜永好篇。"]},{"t":"又次韵帅初诸前七首 其六","f":"七言绝句","c":["荷衣萧飒甘谋拙，毡笠峥嵘任命通。","祇为爱山忙入剡，不因思鲙始归东。"]},{"t":"又次韵帅初诸前七首 其五","f":"七言绝句","c":["幻景为生何短长，痴人得梦亦推详。","餐英漫效独清屈，饮乳谁皆百世苍。"]},{"t":"又次韵帅初诸前七首 其四","f":"七言绝句","c":["世上纷纷博一卢，案头矻矻守三馀。","牢辞门外鸡豚社，菜味深长手灌锄。"]},{"t":"又次韵帅初诸前七首 其三","f":"七言绝句","c":["世机毒甚含沙蜮，民命危于减水鱼。","幸有柴门自深闭，不妨窗下蠹残书。"]},{"t":"又次韵帅初诸前七首 其二","f":"七言绝句","c":["青春本是耐官劳，却入山居便养高。","清话一閒甜蚁梦，黄尘万事等鸿毛。"]},{"t":"又次韵帅初诸前七首 其一","f":"七言绝句","c":["三閒老屋坐屏山，梅影横斜细竹斑。","寡欲自能坚铁脊，长生何必问金丹。"]},{"t":"三次前韵二首 其二","f":"七言绝句","c":["花本伤时不肯香，酒无赊处亦空忙。","便逢花酒如何醉，回首凄烟锁景阳。"]},{"t":"三次前韵二首 其一","f":"七言绝句","c":["东风吹送世閒尘，斜日消凝洛下春。","谁料马蹄成怪事，旁观自有豫知人。"]},{"t":"上巳酒边即事示女冲二首 其二","f":"七言绝句","c":["年华浮动酒中心，笑向吾前满满斟。","犹喜家贫诗礼在，一杯真率胜山阴。"]},{"t":"上巳酒边即事示女冲二首 其一","f":"七言绝句","c":["女冲踏露折棠花，引得儿童哄一家。","说道今朝修禊日，暂抛针线答年华。"]},{"t":"与西寺月石桥二首 其二","f":"七言绝句","c":["相逢相约到云閒，欲往从人却又还。","留取有馀无尽意，眼中处处见西山。"]},{"t":"与西寺月石桥二首 其一","f":"七言绝句","c":["脊梁硬竖支撑佛，心地平铺济渡人。","不比天台无用物，祇将奇险诳愚民。"]},{"t":"与弟侄观小圃梅花二首 其二","f":"七言绝句","c":["是则看花要及时，看花到实不妨迟。","前贤亦有留佳句，绿叶成阴子满枝。"]},{"t":"与弟侄观小圃梅花二首 其一","f":"七言绝句","c":["看花须看未开时，到七分开看已迟。","前辈咏梅多此意，水边竹外两三枝。"]},{"t":"与徐国英坐西窗渴睡中得四句","f":"七言绝句","c":["古语相宜数日陪，西风未放木犀开。","子方兴尽欲归去，小雨又从溪外来。"]},{"t":"小学识愧 其二","f":"七言绝句","c":["指点方名屑训蒙，一方才解四方通。","定知第一番开说，万水朝宗是正东。"]},{"t":"小学识愧 其一","f":"七言绝句","c":["字画向来虽小技，儿时欲学亦难详。","点妆但莫如新妇，端正终须自老苍。"]},{"t":"小学识愧 其三","f":"七言绝句","c":["工夫靠里方为学，时习奚分幼壮年。","何幸席閒提掇紧，最明新处是陈篇。"]},{"t":"小宴偶成","f":"七言绝句","c":["小宴珊瑚月未明，满堂欢笑杂蛙声。","明朝此会知谁续，试把镫花仔细评。"]},{"t":"元夕应人求题酒肆镫","f":"五言绝句","c":["镫花三五夜，鼓笛十分春。","欲见太平事，谁非沈醉人。"]},{"t":"元宵薇山内弟酒边五首 其三","f":"七言绝句","c":["火是人生日用资，难凭回禄做儿嬉。","千镫照夜成何事，一点疏防万屋危。"]},{"t":"元宵薇山内弟酒边五首 其二","f":"七言绝句","c":["镫宵处处是春台，尽夜还家亦快哉。","说与诸儿此行好，满襟带得义风回。"]},{"t":"元宵薇山内弟酒边五首 其一","f":"七言绝句","c":["青镫连夜得论情，瓦缶方淫独古声。","人意好时天亦应，满山风雨忽开晴。"]},{"t":"午景书怀","f":"七言绝句","c":["虚斋檐马自丁东，却在莺啼燕语中。","整屐欲寻花信息，不知柳絮已随风。"]},{"t":"王得淦招饮席上二首 其二","f":"七言绝句","c":["太史应须奏德星，老夫相与證高情。","杯盘楚楚饶诗兴，写出人閒淡处声。"]},{"t":"王得淦招饮席上二首 其一","f":"七言绝句","c":["亲戚疏疏已晓星，杯中滴滴是真情。","近来此酒谁家有，除却旗亭无笑声。"]},{"t":"丙戌人日与内侄汪景渊同饮于宜晚二首 其二","f":"七言绝句","c":["危世相逢三载閒，春风杯酒此时难。","双溪不是无风月，世味何如菜芋盘。"]},{"t":"丙戌人日与内侄汪景渊同饮于宜晚二首 其一","f":"七言绝句","c":["忆昔儿嬉祖母旁，如今甲子一周强。","昼窗三世亲亲话，分付儿孙此意长。"]},{"t":"代弟茝咏梅画十景 其九 飞花","f":"七言绝句","c":["独占初春早卸芳，肯随桃李炫侬妆。","如今不到寿阳额，自做孤村流水香。"]},{"t":"代弟茝咏梅画十景 其八 风前","f":"七言绝句","c":["打头二十四番信，吹透天香雪里枝。","总被诗人收拾去，封姨正自未能知。"]},{"t":"代弟茝咏梅画十景 其二 古枝","f":"七言绝句","c":["分甘冷落傍朱门，傲雪欺霜百岁根。","惆怅西湖人不见，暗香依旧月黄昏。"]},{"t":"代弟茝咏梅画十景 其一 先春","f":"七言绝句","c":["才得江南第一春，竹篱茅舍便精神。","百花头上无相识，只有东风是故人。"]},{"t":"代弟茝咏梅画十景 其六 依竹","f":"七言绝句","c":["香在溪头古晋林，潇潇风雨惯曾禁。","休寻白玉堂前梦，自有此君知此心。"]},{"t":"代弟茝咏梅画十景 其五 依松","f":"七言绝句","c":["处子从来不世妆，老苍相对本相忘。","犹嫌曾受秦封污，冷笑无言祇自香。"]},{"t":"代弟茝咏梅画十景 其四 卧烟","f":"七言绝句","c":["生香自恨玉为容，谁放晨光浅碧笼。","隐约风标难画处，邯郸人在梦炊中。"]},{"t":"代弟茝咏梅画十景 其三 宜月","f":"七言绝句","c":["斜斜瘦影两三枝，只许寒窗人自知。","犹恨嫦娥收不尽，却归羌管曲中吹。"]},{"t":"代弟茝咏梅画十景 其十 结实","f":"七言绝句","c":["碧实圆成重压枝，万红千紫竟何知。","是虽不入甜人口，留得青酸有用时。"]},{"t":"代弟茝咏梅画十景 其七 雪里","f":"七言绝句","c":["天花包尽世閒羞，也到孤山老树头。","寄语东风为吹拂，本来面目自风流。"]},{"t":"出门偶成","f":"七言绝句","c":["双鹭飞飞高复低，复低飞下近山溪。","一声樵唱山前路，却又飞归翡翠西。"]},{"t":"外孙黄相儿求写送春三首并示","f":"七言绝句","c":["相儿一揖笑嬉嬉，要写酴醾架下诗。","留取他年时展看，外家风景有当时。"]},{"t":"用梅山醉中韵三首 其三","f":"七言绝句","c":["吟搜菜味诗宜瘦，睡足花时梦亦香。","閒也曾忙老彭泽，存而无用古灵光。"]},{"t":"用梅山醉中韵三首 其二","f":"七言绝句","c":["满世杨花桃李妆，自家采采芷兰香。","无从捉鼻如安石，相与齐眉有孟光。"]},{"t":"用梅山醉中韵三首 其一","f":"七言绝句","c":["一窗桃李夹垂杨，一卷离骚一炷香。","闭眼坐来开眼笑，到无言处是春光。"]},{"t":"示侄泳求牡丹","f":"七言绝句","c":["见说东家有牡丹，有花欲觅数枝看。","若还溺爱悭分送，却与无花是一般。"]},{"t":"伤春","f":"七言绝句","c":["杜鹃非是翠芳残，底事年年叫出山。","纸帐竹床清到底，不堪声入梦魂閒。"]},{"t":"似居简","f":"七言绝句","c":["老岁虽寻相近寺，危时欲见得交人。","平生自有凌云志，只恐峰高不受邻。"]},{"t":"似僧一宁","f":"七言绝句","c":["邂逅交情云水閒，茶瓯香鼎话清閒。","他年燕坐千峰上，认取一山山外山。"]},{"t":"似僧耕野云","f":"七言绝句","c":["浮云一片出天涯，南北东西总是家。","飞到五山山绝顶，风雷变化雨河沙。"]},{"t":"有感","f":"七言绝句","c":["天将转冷热连日，云欲开晴雨数丝。","造物从容消长处，盍将人事此中推。"]},{"t":"次儿瀹以诗四首道各意因两用其韵 其七","f":"五言绝句","c":["俗氛炎郁攸，世燄毒恶来。","清当友孤竹，隐当友仙梅。"]},{"t":"次云岫惠茶","f":"七言绝句","c":["满啜禅林五味茶，清风吹散事如麻。","客中邂逅真奇绝，不比寻常贼破家。"]},{"t":"次儿泌韵","f":"七言绝句","c":["门外风尘付一吁，何妨稼圃学樊须。","由由本自人难浼，皎皎奚忧我易污。"]},{"t":"次韵东平赵益三首 其二 凤花","f":"七言绝句","c":["翠红翼翼宝坊閒，曾入瑶宫白玉阑。","飞上朝阳瑞天下，灵根变化本无难。"]},{"t":"次韵东平赵益三首 其一 龙松","f":"七言绝句","c":["修鳞化作偃松寒，数百年閒一梦看。","何似起来云拥去，为天行雨万民欢。"]},{"t":"次单君范袖来汪西皋所撰咏秋十章以示因和之十绝 其九","f":"七言绝句","c":["梦断康衢立极谣，心如泥絮看萍飘。","一清盍与金溪水，同味谁争盐海潮。"]},{"t":"次单君范袖来汪西皋所撰咏秋十章以示因和之十绝 其四","f":"七言绝句","c":["自古年年自有秋，悲秋元只是閒愁。","感时祇有长庚子，说到衣冠成古邱。"]},{"t":"次单君范袖来汪西皋所撰咏秋十章以示因和之十绝 其六","f":"七言绝句","c":["木犀风了桂花风，几日中閒景不同。","惟有黄花偏耐老，饱收霜露玉成功。"]},{"t":"次单君范袖来汪西皋所撰咏秋十章以示因和之十绝 其十","f":"七言绝句","c":["昏眵望杳水云村，好句从来风月人。","瓦缶不量追大吕，冰壶何惜受纤尘。"]},{"t":"次单君范袖来汪西皋所撰咏秋十章以示因和之十绝 其一","f":"七言绝句","c":["鸦带残阳入翠微，纷纷黄叶向人飞。","西风不管人閒事，雁自南飞燕自归。"]},{"t":"次单君范袖来汪西皋所撰咏秋十章以示因和之十绝 其三","f":"七言绝句","c":["平生念不到轻肥，砧杵凄凄捣布衣。","说与妻孥贫自好，相看一笑有春晖。"]},{"t":"次单君范袖来汪西皋所撰咏秋十章以示因和之十绝 其五","f":"七言绝句","c":["飞飞鸿雁旧山川，有泪沾衣感昔贤。","猛拍阑干因猛省，从来沧海变桑田。"]},{"t":"次单君范袖来汪西皋所撰咏秋十章以示因和之十绝 其八","f":"七言绝句","c":["平生四海有知心，宿草秋风只感今。","独向西皋一回首，未曾平面已兰金。"]},{"t":"次单君范袖来汪西皋所撰咏秋十章以示因和之十绝 其二","f":"七言绝句","c":["蘋蓼汀洲红白分，忧心触景自如醺。","鸿飞本欲冥冥去，万里长天不放云。"]},{"t":"次单君范袖来汪西皋所撰咏秋十章以示因和之十绝 其七","f":"七言绝句","c":["露穫归来妇爨催，西风满屋饭香来。","痴儿得饱牛衣舞，也要人呼小老莱。"]},{"t":"次和天童僧惠杲书记袖诗来访三首 其三","f":"七言绝句","c":["出山相过便东行，水落山空一别轻。","留得清诗照窗几，万花妆里独梅兄。"]},{"t":"次和天童僧惠杲书记袖诗来访三首 其二","f":"七言绝句","c":["省话何须吞炭瘖，安贫便是直钩心。","看来世事真飘瓦，笑杀时流重注金。"]},{"t":"次和天童僧惠杲书记袖诗来访三首 其一","f":"七言绝句","c":["当年飓捲地轮移，拄杖东还云与飞。","太白岩前绿阴下，相逢无语听催归。"]},{"t":"次和梅山弟二首 其二","f":"七言绝句","c":["心如古井已无波，无奈山林宿兴多。","何幸风流存晋宋，不妨诗律效阴何。"]},{"t":"次和梅山弟二首 其一","f":"七言绝句","c":["马上功名马伏波，少游终是胜兄多。","如今都付忘言处，醉向黄花奈我何。"]},{"t":"次前人似任叔实","f":"七言绝句","c":["字字真真幻幻心，讲毡须体美中箴。","分明示我猪龙训，剪刷成他鸾鹄襟。"]},{"t":"次前韵二首 其二","f":"七言绝句","c":["竹溪诗笔几曾乾，遗我新诗照眼寒。","不用寻梅霜月底，祇将诗句作梅看。"]},{"t":"次前韵二首 其一","f":"七言绝句","c":["玉奴留下唾花乾，夜逐嫦娥入广寒。","不许世人轻著眼，漫教对此细评看。"]},{"t":"次前韵二首似前育王寺主僧如日 其二","f":"七言绝句","c":["桂渐吹香菊渐斑，西风送步得高攀。","天开图画著二老，我亦何妨一笑閒。"]},{"t":"次前韵似云岫","f":"七言绝句","c":["一帘云影隔尘埃，小小禅心为客开。","坐久不知风雨恶，柏炉香里话诗来。"]},{"t":"次前韵寄天宁老可举避生日于西山","f":"七言绝句","c":["迎锡清风扫宿埃，烟霏空翠画图开。","西山山上千年鹤，认取年年一度来。"]},{"t":"次前韵酬王景云见和三首 其三","f":"七言绝句","c":["与子相逢别未长，新诗寄我寂寥乡。","嚼情咀义心如醉，背立西风不自将。"]},{"t":"次前韵酬王景云见和三首 其二","f":"七言绝句","c":["竹边结屋饱幽清，疏落樽前文字盟。","子到午山侬亦到，月边云峤得论情。"]},{"t":"次前韵酬王景云见和三首 其一","f":"七言绝句","c":["我家西谷子鄞东，西望云山百里中。","回首十年尘底别，更无书落雁天风。"]},{"t":"次韵儿瀹六月十二日登东坑岭","f":"七言绝句","c":["欲寿吾前酒一行，走三百里火云程。","热时却有寒时节，汝母梅花腊底生。"]},{"t":"次韵八侄三首 其三","f":"七言绝句","c":["花开便是候催归，济楚生香清复微。","遥想折来深院宇，似初匀粉小青衣。"]},{"t":"次韵八侄三首 其二","f":"七言绝句","c":["素妆青盖送春归，似不禁风体力微。","收拾韵香归酒盏，惜花何惜醉淋衣。"]},{"t":"次韵八侄三首 其一","f":"七言绝句","c":["春色三分一未归，雪肌风态露春微。","东风且作枝头主，莫把工夫绣地衣。"]},{"t":"次韵上乘寺主僧如岳咏菊","f":"七言绝句","c":["万紫千红各炫名，纷纷儿女哄春荣。","屈园秋种无人顾，独遇陶潜气始平。"]},{"t":"次韵女洸九日坐病与泌诗","f":"七言绝句","c":["翻海谁能实漏卮，世情分数逐时支。","三年两满何须计，父子初心要自知。"]},{"t":"次韵五月六日醵饮茂林","f":"七言绝句","c":["一味清风万竹阴，自行自坐见初心。","已抛仙侣枕中梦，能听老陶琴外音。"]},{"t":"次韵内弟贝端甫家醉中","f":"七言绝句","c":["轩窗小小受千山，杯酒匆匆胜肆筵。","满面春风相照处，话心只话数年前。"]},{"t":"次韵内弟汪英春来弟家省母二首 其二","f":"七言绝句","c":["绿衣何曾解老怀，彩褐朅来舞春阶。","方知无忝所生处，不犯河魁也是斋。"]},{"t":"次韵内弟汪英春来弟家省母二首 其一","f":"七言绝句","c":["菽水可欢须且住，粟布相容何必去。","纵然有约奉归轩，也待春程香煖处。"]},{"t":"次韵仇生五首 其五","f":"七言绝句","c":["羡君诗思九河疏，混混泉源只一初。","我欲驱驰无本领，激沟浍水狎蛙鱼。"]},{"t":"次韵仇生五首 其四","f":"七言绝句","c":["诗筒狎至补前疏，快似西风捲峡初。","一片襟怀谁似友，曾从仙李跨鲸鱼。"]},{"t":"次韵仇生五首 其三","f":"七言绝句","c":["交不缘诗有密疏，诗能宣写此心初。","但从礼义中游戏，便是趋庭孔伯鱼。"]},{"t":"次韵仇生五首 其二","f":"七言绝句","c":["学晚唐诗俗见疏，君家句法到黄初。","淡交顾辱联翩赠，熊掌方尝又得鱼。"]},{"t":"次韵仇生五首 其一","f":"七言绝句","c":["一春风雨笑谈疏，明日南风夏又初。","忽枉翠裾诗在手，胜如书尺寄双鱼。"]},{"t":"次韵月窗兄惜别四首 其四","f":"七言绝句","c":["为侬传语竹窗兄，逢著行人也寄声。","聚散在天终有定，岁寒三友见交情。"]},{"t":"次韵月窗兄惜别四首 其三","f":"七言绝句","c":["记得溪山两袂分，一溪流水落花春。","青骢马上休回首，只见云山不见人。"]},{"t":"次韵月窗兄惜别四首 其二","f":"七言绝句","c":["几载诗盟两见心，自从别后可曾寻。","夜来梦见匆匆散，杜宇西窗月未沈。"]},{"t":"次韵月窗兄惜别四首 其一","f":"七言绝句","c":["分付浮生一字休，欲休不得是离愁。","如今祇怕归无准，心在丹山最上头。"]},{"t":"次韵王文甫先生二首 其二","f":"七言绝句","c":["富贵谁能讯女星，得师自分满平生。","河汾他日书成后，王魏中閒亦有名。"]},{"t":"次韵王文甫先生二首 其一","f":"七言绝句","c":["赫赫光华夺景星，斯文宗主在先生。","他年奏赋通明殿，已信君王不敢名。"]},{"t":"次韵史猷父来见","f":"七言绝句","c":["诗书门户耿馀光，残月孤星各一方。","白首相逢笑相问，何如耆旧在襄阳。"]},{"t":"次韵石瑶林帅干见贺","f":"七言绝句","c":["溪头风浪起虚传，宽大遭逢台阃贤。","见说襄城鞭卫士，清朝曾恕范忠宣。"]},{"t":"次韵刘生蝶叶交飞","f":"七言绝句","c":["荷衰菊老柳微黄，蝶舞风林叶共狂。","阆苑无花留不住，飞来学做小春忙。"]},{"t":"次韵刘后村所赠延庆主僧圭复翁诗三首 其三","f":"七言绝句","c":["一色时妆漆染丝，淡中头绪自相知。","后村已入神仙洞，留得同庚伴赋诗。"]},{"t":"次韵刘后村所赠延庆主僧圭复翁诗三首 其二","f":"七言绝句","c":["清到复翁方是清，不求名处莫逃名。","南湖一片平铺水，中有拍天波浪声。"]},{"t":"次韵刘后村所赠延庆主僧圭复翁诗三首 其一","f":"七言绝句","c":["古往今来几过帆，天高地下一浮庵。","与翁相见亦偶尔，一笑无言意自参。"]},{"t":"次韵如岳惠茶","f":"七言绝句","c":["槐窗梦断凤团香，松涧分来雀嘴尝。","句引清风发吟兴，与师意思一般长。"]},{"t":"次韵孙古岩立春","f":"七言绝句","c":["一声唤起便成春，向日庭台总可人。","本与东风旧相识，一回相见一回新。"]},{"t":"次韵竹窗兄相招","f":"七言绝句","c":["酒徒元不是高阳，君以诗招语亦香。","虽欲醉归重九日，恐贻亲怒愧王祥。"]},{"t":"次韵吴竹溪谢单景山载酒","f":"七言绝句","c":["杯盘移醉冠春园，酒散人归月在门。","何日喜还供笑语，酌君村酒侑齑盆。"]},{"t":"次韵弟观送牡丹","f":"七言绝句","c":["极目风沙姚魏家，耳边忍听后庭花。","谁能把酒樽前醉，添得临风感岁华。"]},{"t":"次韵张子华七夕","f":"七言绝句","c":["郎自牵牛女自梭，驾言一岁一相过。","不应妄念忘机杼，如此风波亦渡河。"]},{"t":"次韵张君寿来见二首 其二","f":"七言绝句","c":["大学门庭不易登，参前新意逐时生。","须教一敬存神舍，莫是多吟费管城。"]},{"t":"次韵张君寿来见二首 其一","f":"七言绝句","c":["万错生于一动閒，老夫不是不知还。","春风百里回头处，莫怪移文到北山。"]},{"t":"次韵汪英春九日酒边","f":"七言绝句","c":["有客相过风雨秋，唾飞珠玉胜珍羞。","但知女似谢道蕴，不道吾为马少游。"]},{"t":"次韵邑宰徐何谦道中咏风雨中闻藕花香","f":"七言绝句","c":["眼空尘世粉红娇，看了濂溪兴自饶。","风雨中閒曾著句，满身身到庆登桥。"]},{"t":"次韵陈帅干喜雨二首 其二","f":"七言绝句","c":["一雨何关百里雷，天心端为众心回。","閒时试向龙君觅，未必滂沱应手来。"]},{"t":"次韵陈帅干喜雨二首 其一","f":"七言绝句","c":["何事犹屯水与雷，夜看云汉叹昭回。","五龙一日齐行雨，且莫嫌他欠早来。"]},{"t":"次韵如岳醵饮西峰寺分韵成诗十四首见寄 其一","f":"七言绝句","c":["人世浮浮风里尘，不须更问果何因。","有时意思悠然处，流水青山便是亲。"]},{"t":"次韵如岳醵饮西峰寺分韵成诗十四首见寄 其十一","f":"七言绝句","c":["小小杯盘共话情，兹行聊尔过浮生。","瘦吟学士如工部，楷法书来近率更。"]},{"t":"次韵如岳醵饮西峰寺分韵成诗十四首见寄 其十","f":"七言绝句","c":["老佛眉閒屋漏愁，残廊脚下草光浮。","谁能饥坐芦穿膝，莫问神通石点头。"]},{"t":"次韵如岳醵饮西峰寺分韵成诗十四首见寄 其十四","f":"七言绝句","c":["游了南山山外山，北山下住更幽閒。","消磨永日何妨睡，受用清风不用还。"]},{"t":"次韵如岳醵饮西峰寺分韵成诗十四首见寄 其六","f":"七言绝句","c":["萧萧四壁住残生，不学神仙不学僧。","有酒未能忘北海，种瓜且自学东陵。"]},{"t":"次韵如岳醵饮西峰寺分韵成诗十四首见寄 其四","f":"七言绝句","c":["天街追逐边尘乱，更点听残钟鼓院。","归舟便觉昔年非，高枕已忘前日倦。"]},{"t":"次韵奉慈寺主居简","f":"七言绝句","c":["纳交虽浅自知深，一见如抽病眼针。","已约飞云狎来往，谁知峰顶有千寻。"]},{"t":"次韵前人补试落归曹娥待潮","f":"七言绝句","c":["谒祠江上且归休，有命何须企碧流。","好把一言寤明主，声名当不减千秋。"]},{"t":"次韵前人城北春行","f":"七言绝句","c":["醉游不省路东西，可意花枝手自提。","好景未知何处是，漫随蜂蝶过芳畦。"]},{"t":"次韵前人新晴三首 其三","f":"七言绝句","c":["院静春深冷麝煤，怕逢花委细苍苔。","小桃却自红如锦，笑倚东风醉入腮。"]},{"t":"次韵前人新晴三首 其二","f":"七言绝句","c":["泥香风软燕忙时，宿雨微中起较迟。","试捲珠帘问花事，画鞦韆外袅晴丝。"]},{"t":"次韵前人新晴三首 其一","f":"七言绝句","c":["流莺恰恰报新晴，如醉春光畅踏青。","金犊车前诗料足，不妨分付入骚情。"]},{"t":"次韵前人壁閒诗 其一","f":"七言绝句","c":["万宇腥埃风满山，只饶二十里云閒。","要知人好境不好，最怕身闲心未闲。"]},{"t":"次韵袁司理送行三首 其三","f":"七言绝句","c":["潇洒秋光山水窟，木犀香底细评诗。","今朝携手明朝别，此会一生能几时。"]},{"t":"次韵袁司理送行三首 其二","f":"七言绝句","c":["阴六阳三天者定，重逢樽酒定何时。","但须别后频相问，来往翔鸿各寄诗。"]},{"t":"次韵袁司理送行三首 其一","f":"七言绝句","c":["别友相逢情最好，相逢还别若为情。","看君腾踏飞黄去，记取清镫影里盟。"]},{"t":"次韵屠仰之咏火","f":"七言绝句","c":["孔孟光华不死生，楚秦灰炬漫纷更。","莫将烧叶焙浮烬，要把盘根养宿明。"]},{"t":"次韵惟西堂巧山二首 其二","f":"七言绝句","c":["一片灵心著古风，清吟披拂到衰翁。","从教湖海相传去，知我曾来茅屋中。"]},{"t":"次韵惟西堂巧山二首 其一","f":"七言绝句","c":["清风明月本无边，我亦寻盟到白莲。","青玉轩前坐来久，淡中滋味自相贤。"]},{"t":"次韵梅山弟醉吟七首 其七","f":"七言绝句","c":["人于忙处不知老，诗到醉时方是真。","相对梅山几杯酒，不知身亦是今人。"]},{"t":"次韵梅山弟醉吟七首 其六","f":"七言绝句","c":["开眼门外世梦短，忘情樽前閒意长。","邂逅当有赤松子，歌舞何用楚兰香。"]},{"t":"次韵梅山弟醉吟七首 其五","f":"七言绝句","c":["蚊翼只为黄昏忙，鹄心自与青天长。","世人皆失我独得，春风浩浩诗书香。"]},{"t":"次韵梅山弟醉吟七首 其四","f":"七言绝句","c":["鱼眼死也依然张，鹤颈生来如此长。","凡物不齐各有分，不须逐臭存吾香。"]},{"t":"次韵梅山弟醉吟七首 其三","f":"七言绝句","c":["隐处是角里先生，放游是司马子长。","试问梅山老居士，判断两家谁最香。"]},{"t":"次韵梅山弟醉吟七首 其二","f":"七言绝句","c":["暗檐行吟梅影瘦，午窗坐睡檀丝长。","不作上下四方梦，何妨参受三峰香。"]},{"t":"次韵梅山弟醉吟七首 其一","f":"七言绝句","c":["高明所志希贤圣，愚暗惟知事鬼神。","老我激昂非矫物，本心标榜未输人。"]},{"t":"次韵梅山送牡丹二首 其二","f":"七言绝句","c":["毒雾腥尘涴色香，无知蜂蝶自乾忙。","醉时烦恼不须醉，三斗谁能向汝阳。"]},{"t":"次韵梅山送牡丹二首 其一","f":"七言绝句","c":["姚根魏拨两京贵，蜀本黟枝南度春。","今日东风为谁好，花香不到独醒人。"]},{"t":"次韵雪窦寺主僧炳同招游山二首 其二","f":"七言绝句","c":["飞下吟笺墨妙斑，空拳难对敌家攀。","肯分半榻清风况，翻怪诗来挠聒閒。"]},{"t":"次韵雪窦寺主僧炳同招游山二首 其一","f":"七言绝句","c":["万叶逢秋又缬斑，珠林锦镜好追攀。","人生行乐非容易，本是閒人也未閒。"]},{"t":"次韵鹿苑寺一览阁主岳松涧送茶","f":"七言绝句","c":["鹿苑书来字字香，满奁雀舌饷新尝。","有时独坐相思处，一鼎松风午韵长。"]},{"t":"次韵童志道春晚","f":"七言绝句","c":["隔窗啼鸟梦惊残，沈麝香销冷博山。","只枕半敧閒猛省，又添一日在人閒。"]},{"t":"次韵童尚质","f":"七言绝句","c":["落日孤烟水绕村，山家灯火已昏昏。","幽人事业书窗底，自读离骚半掩门。"]},{"t":"次韵答张子开教授","f":"七言绝句","c":["两翁相对五里近，一病同眠八月天。","彼此医治须努力，要成欢醉菊花前。"]},{"t":"次韵椿长老惠莲花扇","f":"七言绝句","c":["莲花法界走舆台，两扇香风为我开。","藜藿皮毛消不尽，若为回向我如来。"]},{"t":"次韵僧云岫见寄","f":"七言绝句","c":["忆昔宫花压帽檐，如今野褐替朝衫。","邯郸梦觉身犹在，安得寒山喝破岩。"]},{"t":"次韵僧云岫寄东皋寺主智恭","f":"七言绝句","c":["闻说东皋绝点埃，笑飞铁锡把山开。","何须一面方相识，曾见藕花诗句来。"]},{"t":"次韵戴帅初村园杂兴二首 其二","f":"七言绝句","c":["新园本是无多地，几步低平几步高。","已逝江湖分雁啄，且从溪谷到龟毛。"]},{"t":"次韵戴帅初村园杂兴二首 其一","f":"七言绝句","c":["田不充耕漫垦山，焦劳新做鬓毛斑。","牛歌方见平生戚，鱼釜何曾饿死丹。"]},{"t":"次韵戴帅初觅茶子二首 其二","f":"七言绝句","c":["新诗著意不曾疏，苦觅茶栽胜索租。","搜送坚霜千碧颗，难酬五十斛明珠。"]},{"t":"次韵戴帅初觅茶子二首 其一","f":"七言绝句","c":["风流清苦自成家，要撷春香煮雪花。","知味不随鸿渐唾，剡翁自种剡翁茶。"]},{"t":"次韵戴帅初架阁剡居四首 其四","f":"七言绝句","c":["隔一青山能几里，频频聚首约方来。","生涯冷淡浑如此，输与斑衣学老莱。"]},{"t":"次韵戴帅初架阁剡居四首 其三","f":"七言绝句","c":["见说三閒松下屋，更无长物累中心。","难忘独有南风操，时到溪山一鼓琴。"]},{"t":"次韵戴帅初架阁剡居四首 其二","f":"七言绝句","c":["青春踏过洛阳尘，今却寻盟郑子真。","天下方酣施夺事，村中自有逊耕民。"]},{"t":"次韵戴帅初架阁剡居四首 其一","f":"七言绝句","c":["书担随身又入山，危途步步转头看。","近于潇上二三里，难似江西十八滩。"]},{"t":"西上罕岭","f":"五言绝句","c":["此去向南西，山高山复低。","不逢清话客，已觉倦扶藜。"]},{"t":"呈竹石亭","f":"七言绝句","c":["说道疏时元是密，偶于忙处得寻閒。","宿愁复岭重山外，新趣清风明月閒。"]},{"t":"呈龄叟二首 其二","f":"七言绝句","c":["老师神用笑谈中，不但能降大小空。","自谓我心顽似铁，也随柳絮舞春风。"]},{"t":"呈龄叟二首 其一","f":"七言绝句","c":["溪山五里眼花中，万变风光一总空。","惟有老师无处语，依然只是旧家风。"]},{"t":"应百里李天益来求作奉川十咏似之 其一 广莫轩","f":"七言绝句","c":["高山处处著虚轩，来此凭阑便欲仙。","下视浮云隔黄雾，平迎行日上青天。"]},{"t":"应百里李天益来求作奉川十咏似之 其六 凤花","f":"七言绝句","c":["谁把深红浅绿蟠，羽毛飞动倚风阑。","时人不识来仪瑞，只向花前想像看。"]},{"t":"应百里李天益来求作奉川十咏似之 其八 石夫人","f":"七言绝句","c":["千尺嶙峋直立形，流传神应挟风霆。","石身本聚山川气，便是人心聚处灵。"]},{"t":"应百里李天益来求作奉川十咏似之 其七 龙松","f":"七言绝句","c":["皮皴肉紧发苍然，伏雪眠风傲岁年。","不见南阳龙卧者，本心元自直通天。"]},{"t":"应百里李天益来求作奉川十咏似之 其二 庆登桥","f":"七言绝句","c":["一水流南抱县行，一桥在上压溪横。","傍阑多少人观政，要与桥平水与清。"]},{"t":"应百里李天益来求作奉川十咏似之 其四 岳林","f":"七言绝句","c":["传说当年契此翁，偶然来此笑春风。","忽抛布袋归何处，地下天高一阁空。"]},{"t":"应百里李天益来求作奉川十咏似之 其三 虚白观","f":"七言绝句","c":["庭中说法有龙听，龙去庭空水一汀。","独有亭亭岁寒柏，不知人世自青青。"]},{"t":"应百里李天益来求作奉川十咏似之 其五 雪窦","f":"七言绝句","c":["乳峰真可避人閒，上妙高台天可攀。","未说旷怀便笑傲，堪从险处习閒关。"]},{"t":"应百里李天益来求作奉川十咏似之 其十 耀碑潭","f":"七言绝句","c":["微风篆水自成碑，清月磨潭不受疵。","万里此通归去路，扁舟堪载送行诗。"]},{"t":"弟观为众奉里神于丹山僧舍有五绝因趁韵 其五","f":"七言绝句","c":["迎神旧是醉哗场，榷禁方严酒有坊。","幸免叫嚣成鬼市，不妨安稳服农忙。"]},{"t":"弟观为众奉里神于丹山僧舍有五绝因趁韵 其四","f":"七言绝句","c":["老我今年七十二，已无半念到穷通。","北窗一枕羲皇上，日自流西水自东。"]},{"t":"弟观为众奉里神于丹山僧舍有五绝因趁韵 其二","f":"七言绝句","c":["人众由来口铄金，漫从时好答人心。","堪怜寒露冰壶玉，尘满冠巾汗满襟。"]},{"t":"弟观为众奉里神于丹山僧舍有五绝因趁韵 其三","f":"七言绝句","c":["一卷新吟水石香，顿教尘浊变清凉。","唤醒心下十年梦，拜舞薰风面舜廊。"]},{"t":"折梅送友人","f":"七言绝句","c":["一朵梅花直一诗，诗须清似此花枝。","能诗人去花无主，图得重来未落时。"]},{"t":"杜鹃二首 其二","f":"七言绝句","c":["万绿阴中拌死啼，如何日夜不能疲。","料应饱作秋冬梦，恰好如今是醒时。"]},{"t":"杜鹃二首 其一","f":"七言绝句","c":["催归亦是大饶唇，自不能归底劝人。","行止在人终莫劝，只应劝得合归春。"]},{"t":"灵济寺午睡起","f":"七言绝句","c":["江上春风底事寒，主张火匮一雷鼾。","不干酒力浓时困，自是人情熟处安。"]},{"t":"甬东晚望","f":"七言绝句","c":["日落潮生水气昏，回头天际月如痕。","数声寥落渔家笛，吹入蒹葭何处村。"]},{"t":"良月二十一日郡庠置酒炉亭劳余出山且取子美何时一樽酒重与细论文分韵赋诗韵不以及就成十绝 其七","f":"五言绝句","c":["草木味自同，樽酒欢相与。","旧梦忽以醒，恍不知何所。"]},{"t":"良月二十一日郡庠置酒炉亭劳余出山且取子美何时一樽酒重与细论文分韵赋诗韵不以及就成十绝 其十","f":"五言绝句","c":["江湖宽相容，风马留更勤。","襄阳或可传，北山若为文。"]},{"t":"良月二十一日郡庠置酒炉亭劳余出山且取子美何时一樽酒重与细论文分韵赋诗韵不以及就成十绝 其二","f":"五言绝句","c":["兰菊不竞芳，鸿燕各有时。","可以人不如，大哉义曰随。"]},{"t":"良月二十一日郡庠置酒炉亭劳余出山且取子美何时一樽酒重与细论文分韵赋诗韵不以及就成十绝 其八","f":"五言绝句","c":["四座同寮贤，一和长官契。","乐极忘主宾，论到贯粗细。"]},{"t":"良月二十一日郡庠置酒炉亭劳余出山且取子美何时一樽酒重与细论文分韵赋诗韵不以及就成十绝 其九","f":"五言绝句","c":["鸢鱼自飞跃，乌兔自追奔。","中有古道在，难与时情论。"]},{"t":"饮于梅山弟家醉书八首 其三 示圣涯侄","f":"七言绝句","c":["象棋一局酒三杯，此乐都从静处来。","明月清风不轻与，青山流水要相陪。"]},{"t":"饮于梅山弟家醉书八首 其四 示圣涯侄","f":"七言绝句","c":["有约相过亭午天，日斜犹在酒杯閒。","迟迟要待月明去，意在弟兄非在山。"]},{"t":"饮于梅山弟家醉书八首 其一 示圣涯侄","f":"七言绝句","c":["梅山半载在城中，辜负山中月与风。","老我相逢还一笑，弟兄能有几人同。"]},{"t":"饮于梅山弟家醉书八首 其二 示圣涯侄","f":"七言绝句","c":["老我衰颜百念煎，梅山少我十三年。","人生不问寿长短，得一日宽皆是仙。"]},{"t":"饮于梅山弟家醉书八首 其五 示圣涯侄","f":"七言绝句","c":["人閒杯酒易暌乖，祇为闺门意弗谐。","每到梅山醉终日，不闻人语自安排。"]},{"t":"饮于梅山弟家醉书八首 喜见山孙","f":"七言绝句","c":["梅山醉里抱山孙，春入孩颜笑语温。","淡静心田无妄念，祇将诗礼种家门。"]},{"t":"饮于梅山弟家醉书八首 感慨前事","f":"七言绝句","c":["世变其如我醉何，儿孙扶路日西斜。","风吹醒处愁依旧，萧飒乾坤菊两家。"]},{"t":"饮于梅山弟家醉书八首 其六 示圣涯侄","f":"七言绝句","c":["年少心怀早可人，酒边一笑见真醇。","但从此日涵濡去，更把诗书沃此身。"]},{"t":"侄孙矩献醉鳘以一绝复之","f":"七言绝句","c":["年来只识釜中鱼，出海修鳞梦也无。","宝鳘带糟俄入眼，儿童惊动哄寒厨。"]},{"t":"到西山怀赵景文","f":"七言绝句","c":["晓日南窗一煖烘，采薇人去与谁同。","人生毕竟皆如此，休怪浮图只说空。"]},{"t":"到倪■回","f":"七言绝句","c":["七十四岁已见境，九千百步尚寻山。","暗从今日逆数转，能得平生几日閒。"]},{"t":"到梅山处三首 其三","f":"七言绝句","c":["斜阳已在古松閒，杯酒相留未放还。","此是古人真率处，谁知今日有梅山。"]},{"t":"到梅山处三首 其二","f":"七言绝句","c":["溪山有分皆为福，草木无成半计功。","小小梅园胸次阔，到忘言处只春风。"]},{"t":"到梅山处三首 其一","f":"七言绝句","c":["种成梅竹趣何澹，说到诗书心自閒。","滋味深长在物外，尘埃分付与人閒。"]},{"t":"到梅山弟家见瑞香盛开醉书","f":"七言绝句","c":["地因胜境閒中见，花为骚人分外香。","数步出山何世界，一春无事是风光。"]},{"t":"咏不开牡丹","f":"七言绝句","c":["一种仙根自洛阳，春深何事不花生。","芳心未必全羞涩，犹恨东风用力轻。"]},{"t":"咏鹭","f":"七言绝句","c":["玉雪毛衣□□□，平生惯弄碧潺潺。","春风唤起双飞兴，不得鱼虾也入山。"]},{"t":"夜坐书怀","f":"七言绝句","c":["竹窗镫火足相陪，惟怕梅花画角催。","我欲敧眠寻好梦，照人隙月更徘徊。"]},{"t":"宜晚小酌二首 其二","f":"七言绝句","c":["浊酒三杯三代醇，中閒滋味是人伦。","世人毫末成胡越，要看家风我姓陈。"]},{"t":"宜晚小酌二首 其一","f":"七言绝句","c":["天理人伦古到今，一门三世弟兄心。","紫荆树树花如锦，方信春风无浅深。"]},{"t":"招弟辈饮次韵","f":"七言绝句","c":["浅量能消酒几杯，争如俗子厌人来。","明朝定到梅山下，不管梅花开未开。"]},{"t":"泌生日二首 其二","f":"七言绝句","c":["苋藜并日不充饥，玉女于成在此时。","道义于人堪隽永，膏粱从古豢愚痴。"]},{"t":"泌生日二首 其一","f":"七言绝句","c":["为学须知次第功，四书为本要精通。","不须妄起功名想，立得身时禄在中。"]},{"t":"试墨三首 其三","f":"七言绝句","c":["兔毫染上何妨浅，蝉翼写来可放轻。","为爱淡中多酝藉，却嫌浓处太分明。"]},{"t":"试墨三首 其二","f":"七言绝句","c":["墨卿与我是相投，了得时需便罢休。","不见江南井中藏，只为相国寺门留。"]},{"t":"试墨三首 其一","f":"七言绝句","c":["元圭珍重镇书房，紫石磨来滃墨香。","老去苦无閒著述，以分寸计□时长。"]},{"t":"诗寄赵九新娶","f":"七言绝句","c":["风摆柳梢云未乾，痴云妒日正娇寒。","偎香公子新鸳侣，那肯兴心客路难。"]},{"t":"青山下","f":"七言绝句","c":["千顷田畴麦浪花，数家林薄笋抽芽。","休将世事俱归梦，颇喜人生尚有涯。"]},{"t":"临行别单景山","f":"七言绝句","c":["我衰已分龟头缩，君健方知鹤翅掀。","早韭晚菘冬芋栗，尚能时节候高轩。"]},{"t":"南山白云","f":"七言绝句","c":["一片白云飞入山，须臾又出在人閒。","我归十年不复出，说道云閒我更閒。"]},{"t":"复越悟本寺主僧文蔚惠丹剂","f":"七言绝句","c":["师归古越老梅根，我住小丹山下村。","赠我金丹知有意，要生羽翼到云门。"]},{"t":"春午二首 其二","f":"七言绝句","c":["著雨杨花困舞绵，煖风扬作晚晴天。","一场春色归何处，芳草斜阳淡淡烟。"]},{"t":"春午二首 其一","f":"七言绝句","c":["春城那被酒缠绵，燕姹莺娇近午天。","花影满帘庭院寂，碧纱窗迥淡如烟。"]},{"t":"春色十分","f":"七言绝句","c":["今日冠春春十分，画图深处著侬身。","纷纷扑面狂蜂蝶，错认閒人作主人。"]},{"t":"春雪","f":"七言绝句","c":["夜来风雪借冬威，不是东君喜弄奇。","也怕春浓花易过，故将寒力顿花期。"]},{"t":"送许耀卿入越","f":"七言绝句","c":["三宿相留亦是缘，东风吹上镜湖船。","閒心可为流觞事，古眼应探窆石前。"]},{"t":"送君范到下溪头","f":"七言绝句","c":["老来多病脚蹒跚，不觉追行一里宽。","归去闭门还静坐，世途步步是邯郸。"]},{"t":"送单君范赴汪西皋馆","f":"七言律诗","c":["溪水沄沄云出山，行边意思自相关。","欲从杖履吾已老，犹喜诗书君未閒。","道脉不随多事去，文风似放一分还。","纷纷世变忘言外，春在西皋花柳閒。"]},{"t":"送林方叔赴范氏馆","f":"七言绝句","c":["家食城南擅独贤，夜占奎壁半移躔。","东风绛帐浑閒事，先世青毡是宿缘。"]},{"t":"送酒与蒲萄与来石门","f":"七言绝句","c":["山泉酿出苦醅硬，野蔓生来酸子圆。","此味不投甜世界，遣教参透石翁禅。"]},{"t":"重五有感","f":"七言绝句","c":["登高时节殃鸡犬，乞巧风流狎女牛。","何似今朝酹忠魄，残杯一洗世人愁。"]},{"t":"重午酒边四句书宜晚","f":"七言绝句","c":["七十二岁重午酒，百千万变独閒身。","细看榴艾祇自醉，同吊芷兰能几人。"]},{"t":"闻状元是少年","f":"七言绝句","c":["闻说三魁是少年，世閒何必叹才难。","我生亦是奇男子，莫作时人一例看。"]},{"t":"闻剡人望回","f":"七言绝句","c":["跋涉山程往又还，老怀不是爱游山。","为闻父老勤相送，立满溪头几日閒。"]},{"t":"闻莺","f":"七言绝句","c":["当年百啭建章宫，调入新诗丽曲中。","老耳如今听不入，为谁犹自咽东风。"]},{"t":"哭赵观使墓","f":"七言绝句","c":["十载重来古树阴，眼前新冢泪沾襟。","归家当与诸儿说，要识如今展拜心。"]},{"t":"夏五朔旦示都儿学书","f":"五言绝句","c":["老去眼生花，儿方学画鸦。","聊将二十字，要识汝传家。"]},{"t":"留稼山","f":"七言绝句","c":["山蕨如拳未有筋，溪鱼子腹不生鳞。","明朝二味三杯酒，此意良真莫语人。"]},{"t":"酒后四句示梅山弟","f":"七言绝句","c":["濛濛细雨湿春风，家在青山啼鸟中。","有酒可杯书可读，何须门外问穷通。"]},{"t":"高洁堂来见因次前韵三首 其三","f":"七言绝句","c":["诗屋中閒借隙光，老来犹苦未知方。","羡君句法源头活，此意曾参到紫阳。"]},{"t":"高洁堂来见因次前韵三首 其二","f":"七言绝句","c":["君家文献日争光，声价如今重上方。","我老尚知师古学，为搜古集到渠阳。"]},{"t":"高洁堂来见因次前韵三首 其一","f":"七言绝句","c":["室如晦处有通光，内外相须是直方。","认取青毡为旧物，要看鸣凤在朝阳。"]},{"t":"偶成","f":"七言绝句","c":["赤日途中嚼冰雪，红尘城外见林泉。","一时邂逅犹快意，十载清閒我谢天。"]},{"t":"偶成梅山园有酌","f":"七言绝句","c":["易来难去家半里，似有还无雨数丝。","烂醉池边野花下，黄昏犹有未成诗。"]},{"t":"寄南湖主人海雪岑","f":"七言绝句","c":["别雪岑翁不记年，翁今来管四明天。","看翁捲起南湖浪，洗尽浮尘结净缘。"]},{"t":"教学退作二首 其二","f":"七言绝句","c":["话言超出求名外，心力分从负米馀。","幼学得师终有获，立根本处赖深锄。"]},{"t":"教学退作二首 其一","f":"七言绝句","c":["昔年堂上来三鳣，今日溪头领队鱼。","方信卜居初意好，要教同里识诗书。"]},{"t":"晚晴次前韵似前人","f":"七言绝句","c":["雨中菜酒得相陪，天忽安排晚霁开。","明月归途定回首，橘香时节又须来。"]},{"t":"梅山摘其绝为四首和来余因以次韵 其二","f":"七言绝句","c":["辜负山中月与风，心无城市亦山中。","应嫌猿鹤天机浅，要与同行不肯同。"]},{"t":"梅山摘其绝为四首和来余因以次韵 其四","f":"七言绝句","c":["弟兄能有几人同，酒趣诗情冷淡中。","须记松梅满山雪，莫随桃李杏花风。"]},{"t":"梅山摘其绝为四首和来余因以次韵 其三","f":"七言绝句","c":["老我相逢还一笑，杯盘草草自家风。","从人漫说侯鲭好，难与耆英菜味同。"]},{"t":"梅山摘其绝为四首和来余因以次韵 其一","f":"七言绝句","c":["梅山半载在城中，带得山閒物外风。","随境动时元自静，与人和处底须同。"]},{"t":"梅山醉归","f":"七言绝句","c":["山风满松松气香，松香和酒入诗肠。","悠然一醉便归去，如梦未觉无何乡。"]},{"t":"梅初破蕊","f":"七言绝句","c":["朔风惊晓雪花乾，尽力寻梅不道寒。","万事不如初见好，一枝全胜满园看。"]},{"t":"续侄溥赏酴醾劝酒二首 其二","f":"五言绝句","c":["醉时愁亦乐，老去日如年。","惯见红相别，欣逢绿又鲜。"]},{"t":"续侄溥赏酴醾劝酒二首 其一","f":"五言绝句","c":["花有重开日，人无再少年。","相逢拌酩酊，何必备芳鲜。"]},{"t":"绿阴","f":"七言绝句","c":["风枝雨叶渐成阴，扫退浮红浪紫尘。","惭我老苍留本色，安排晚景见新春。"]},{"t":"黄相儿求诗","f":"七言绝句","c":["相儿执笔请翁书，要受持从入学初。","我有至言儿听取，心宜庄敬气宜舒。"]},{"t":"寓建宁推厅送黄子俊","f":"七言绝句","c":["一聆清话觉昏蒙，樽酒何时可再同。","最是秋风恃轻薄，易吹羁袂作西东。"]},{"t":"朝归生日女洸有诗因次韵","f":"七言绝句","c":["老爷不记汝生辰，一见杯盘便是春。","兄姊味言儿记取，同胞皆是读书身。"]},{"t":"游灵济寺方丈酒边","f":"七言绝句","c":["天画轩前酒一杯，爱閒能有几人来。","明朝又入深山去，安得如潮日两回。"]},{"t":"游雪窦杖锡七首 其二 飞雪亭","f":"七言绝句","c":["雪瀑翻崖直下深，自从开辟到如今。","天寒水涩山风急，不断朝宗一派心。"]},{"t":"游雪窦杖锡七首 其三 妙高台","f":"七言绝句","c":["不到兹台四十年，临风独立意悠然。","胸中多少难言事，便欲凭高叩九天。"]},{"t":"游雪窦杖锡七首 其七 杖锡入山亭","f":"七言绝句","c":["山上山根溪一湾，著亭管领此溪山。","云南更在青天际，步一步高从此攀。"]},{"t":"游雪窦杖锡七首 其五 徐凫岩","f":"七言绝句","c":["平揖天风一望来，苍崖万仞两分开。","是中猿鹤亦难得，只有龙云相往回。"]},{"t":"游雪窦杖锡七首 其四 隐潭","f":"七言绝句","c":["何神擎破陇头岩，尽束溪流下碧潭。","潭底有龙能变化，好将霖雨活东南。"]},{"t":"游雪窦杖锡七首 其一 锦镜池","f":"七言绝句","c":["万仞崖擎碧玉台，中閒一镜帖天开。","四时自与幽花对，一点时妆不照来。"]},{"t":"游雪窦杖锡七首 其六 踟蹰岭","f":"七言绝句","c":["石路崔嵬云上头，北云南雪此鸿沟。","谁人题作踟蹰岭，不到山心不当游。"]},{"t":"游蔡峰道中三首 其二 半坑","f":"七言绝句","c":["叠障中閒一隙天，数家茅屋鹳巢边。","逢人试问营生事，笑指岩前煮草烟。"]},{"t":"游蔡峰道中三首 其三 回途望黄沙坑怀朝儿","f":"七言绝句","c":["昨日山前痛忆儿，回头凝望更依依。","如今精爽知何在，采得兰花泣看归。"]},{"t":"游蔡峰道中三首 其一 碧渚庵前","f":"七言绝句","c":["恩袍拜后两周星，今日西行得再经。","休问庵中僧在否，满檐松竹旧时青。"]},{"t":"登慈云阁偶成三首 其三","f":"七言绝句","c":["行人笑我又偷閒，说与行人听我言。","知得浮生皆定分，有谁教汝自煎烦。"]},{"t":"登慈云阁偶成三首 其二","f":"七言绝句","c":["悠悠双鹭趁溪飞，欲带清风何处归。","湖海近来难著脚，灵山深处自知机。"]},{"t":"登慈云阁偶成三首 其一","f":"七言绝句","c":["五里晴行信一筇，入松迎面旧松风。","斜阳归路樵渔笑，翁自何来半醉中。"]},{"t":"答妻侄赵良藩问学","f":"五言绝句","c":["藩兄欲学书，来问学何如。","孝悌为根本，文章特绪馀。"]},{"t":"答法椿长老口占","f":"七言绝句","c":["床前何必问云何，霜顶谁将手自磨。","可是法身真有病，皱眉头处为人多。"]},{"t":"答眚医王东林求□","f":"七言绝句","c":["我抱东林未见心，诸贤诗上见东林。","两瞳不觉针锋到，一瞬清风扫宿阴。"]},{"t":"谢云岫重五送酒粽","f":"七言绝句","c":["金黍琼浆忽到前，方知相近吊湘天。","客中寂寞堪骚屈，暖熟风光出老禅。"]},{"t":"谢单景山载酒同赏牡丹过燕馀","f":"七言绝句","c":["珍重提樽过小园，更呼贵客到樽前。","教人镫下看颜色，知得浮生一梦然。"]},{"t":"谢居简送茶面","f":"七言绝句","c":["银丝饼熟笋供臛，玉糁羹香茶嗽芽。","食粥案头添雅供，不知此味更谁家。"]},{"t":"谢绍兴石梅癯遗本堂二篆书","f":"七言绝句","c":["飞下云閒玉箸书，忽如梦觉揖梅癯。","古来髓脉今谁识，称得山中老饿夫。"]},{"t":"谢戴时芳惠物","f":"七言绝句","c":["蚁绿浮香雪外春，锦翰飞动玉芝新。","山人已约餐松柏，此馈应知是获麟。"]},{"t":"新月","f":"七言绝句","c":["老天大巧亦儿嬉，磨出霜镰仅一眉。","挂向西园瘦梅树，閒心浑怯损南枝。"]},{"t":"蒙斋习庵皆有诗在慈云阁沈端宪又有记文刻石因成二绝 其一","f":"七言绝句","c":["习老蒙翁两达尊，借他僧偈说慈云。","一番入寺一感怆，细读古碑端宪文。"]},{"t":"蒙斋习庵皆有诗在慈云阁沈端宪又有记文刻石因成二绝 其二","f":"七言绝句","c":["景照堂中憩佛骚，阑干凭处接云高。","赋诗时会苦吟甫，破约难留嗜酒陶。"]},{"t":"解剡孝嘉道中答溪民群来遮轿问新知县如何二首并寄李宰 其一","f":"七言绝句","c":["水浅山深土半沙，刀耕火种做生涯。","今年水旱那堪说，存得妻儿能几家。"]},{"t":"解剡孝嘉道中答溪民群来遮轿问新知县如何二首并寄李宰 其二","f":"七言绝句","c":["新知县是旧官员，说与田家汝有缘。","安稳过冬耘二麦，明年才胜似今年。"]},{"t":"锦里观桃","f":"七言绝句","c":["锦里风光分外春，桃花如市趁时新。","斗风车马香尘里，谁是朱门觅水人。"]},{"t":"龄叟得稼山好语因赞之","f":"七言绝句","c":["高怀不是爱山行，钟鼓楼高有宿盟。","今夜老禅联榻卧，定应说到有西成。"]},{"t":"碶头","f":"七言绝句","c":["篙师无力橹声柔，已分前途夜泊舟。","忽报西风吹柁尾，不须斜日到程头。"]},{"t":"横桥观荠","f":"七言绝句","c":["物理元随世事新，静观知是泮宫人。","穿花野荠虽微草，也占年年一分春。"]},{"t":"醉中","f":"七言绝句","c":["乐游原上少年春，安乐窝中快活身。","古到如今能几日，吁嗟天也不由人。"]},{"t":"醉中出门得风字","f":"五言绝句","c":["残生有今日，一醉得清风。","想见羲皇上，人人此乐同。"]},{"t":"醉中示梅山弟二首 其二","f":"七言绝句","c":["两山合秀水流中，茅屋相忘松竹丛。","时节往来容易事，菜汤艾酒一家风。"]},{"t":"醉中示梅山弟二首 其一","f":"七言绝句","c":["夜镫曾醉藕花凉，笋担归来雨亦香。","閒里不妨长聚首，人生能得几斜阳。"]},{"t":"题丹霞洞","f":"七言绝句","c":["丹山高处坐龙宫，山下人归润泽中。","北马一尘飞不到，危时方见有神功。"]},{"t":"题严子陵钓台二首 其二","f":"七言绝句","c":["方信先生大有功，光皇祇是暂时雄。","东都二百年名节，全在桐江一钓风。"]},{"t":"题严子陵钓台二首 其一","f":"七言绝句","c":["才得心安便是通，乘龙非贵钓非穷。","那知碌碌攀鳞者，尽在先生不钓中。"]},{"t":"题思远行业碑","f":"七言绝句","c":["虎溪虽小深似海，截断英雄富贵尘。","却为渊明过溪笑，方知心自有高人。"]},{"t":"燕馀寄月窗兄三首 其三","f":"七言绝句","c":["昨夜还乡已夕阳，夕阳今日已他乡。","回头咄咄相思语，准拟东风好送将。"]},{"t":"燕馀寄月窗兄三首 其二","f":"七言绝句","c":["雨泣镫花夜一更，醉中忘却语诗盟。","料应独立南窗下，猛拍阑干万斛情。"]},{"t":"燕馀寄月窗兄三首 其一","f":"七言绝句","c":["叶叶征衫来自东，相逢笑语竹窗中。","傍人底死催人去，细雨吹凉一夜风。"]},{"t":"薇山处过番石渡遭渡子无礼伤臂因韵二首 其二","f":"七言绝句","c":["唾来不拭如师德，怒至无迁学子颜。","浅眼方知有沧海，恶声宁复到薇山。"]},{"t":"薇山处过番石渡遭渡子无礼伤臂因韵二首 其一","f":"七言绝句","c":["卧如龙奋亮当贵，射可猿通广欲飞。","谁料舟人为敌国，祇应山鸟怪儒衣。"]},{"t":"赞龄叟留东隐二首 其二","f":"七言绝句","c":["一片丹山云出山，慈云高处共清閒。","春风轻借吹嘘力，出本无心也会还。"]},{"t":"赞龄叟留东隐二首 其一","f":"七言绝句","c":["才出家来恩爱轻，师于东隐却关情。","一盂菜饭留分与，方信空门有弟兄。"]},{"t":"赠东隐小师林复祖","f":"七言绝句","c":["万木彫零独有松，雪霜风里几春冬。","须知受变方成物，直上云霄舞翠龙。"]},{"t":"赠茅意山主簿","f":"七言绝句","c":["旅锁倾城慰寂寥，诗篇到眼见贤劳。","三年鸾凤风声好，万里骅骝地步高。"]},{"t":"赠赵月堂","f":"七言绝句","c":["乾坤惨淡真愁绝，民物伤残欲活难。","说相说医当及此，区区衰病不须看。"]},{"t":"戴仲伦求诗","f":"七言绝句","c":["来翁摊纸要求诗，犹胜儿童弱弄嬉。","参得纯公行乐意，傍花随柳待他时。"]},{"t":"乙卯乡贡鹿鸣宴次韵","f":"七言律诗","c":["结发书痴气吸川，壮年才得预宾筵。","射穿杨叶心何武，梦入梅花骨已仙。","设席肆筵劳送上，著鞭跨马欲飞前。","令君早晚朝天去，桃李妍春正耐烟。"]},{"t":"七十见梅有感","f":"七言律诗","c":["万木都由冬折磨，孤根却做老生涯。","寒心欲吐知谁主，瘦骨相依有自家。","祇许江南鸿雁见，肯交春后蝶蜂哗。","风吹不断西湖梦，一曲从他月落笳。"]},{"t":"七月望郡庠赋秋声诗且欲不犯题字及见所作良可发笑因赋二首示诸儿 其一","f":"七言律诗","c":["天教少昊管金行，发越清商妙莫名。","万宇虚凉机自动，千林摇落气难平。","怒为伍子潮江吼，细入欧公夜壁鸣。","最是幽窗多感处，数声唳月雁南征。"]},{"t":"七月望郡庠赋秋声诗且欲不犯题字及见所作良可发笑因赋二首示诸儿 其二","f":"七言律诗","c":["气应商声惨又清，人閒难听亦难名。","非神非鬼洞庭乐，为鹤为风淝水兵。","老叶自吟高处调，寒蛩相趁闹中鸣。","西风机籁年年事，分付与天心自平。"]},{"t":"九月十日乡人醵饮丹山分韵得东字","f":"七言律诗","c":["山光肃肃净杉松，草草提携里曲同。","不是休官住林下，无缘问菊到篱东。","世途险迫閒为福，乡谊绸缪醵有功。","酒散月明多感处，牛山故国正西风。"]},{"t":"九月十日醵饮丹山","f":"七言律诗","c":["举头又是菊花天，走遍山林命苟全。","忍赋庚寅伤乱世，漫书甲子记流年。","陶篱一醉虚抛久，萧寺重游梦觉然。","今是何时成此会，教人平地说神仙。"]},{"t":"二月九日偶成","f":"七言律诗","c":["老境何须更问年，得须臾活便翛然。","平生交际无金谷，穷健中閒自葛天。","终日闭门知拙味，有时放杖信嬉缘。","儿孙子曰一声处，已觉诗书世的传。"]},{"t":"二月二十五日醉吟","f":"七言律诗","c":["午酒三杯率处真，不知门外有风尘。","溪山花木一帘影，兄弟妻孥满屋春。","万事到头皆有命，两閒立脚要求仁。","羲皇以上已难问，且做渊明左右人。"]},{"t":"二月十八日过邑有感二首 其二","f":"七言律诗","c":["说著时难心自寒，斜阳焦土更无边。","故家空梦莺花地，残户不成蚕麦天。","造物未应终绝物，今年莫省是何年。","郁攸独免侵乡校，也向斯文要结缘。"]},{"t":"二月十八日过邑有感二首 其一","f":"七言律诗","c":["植杖东风立晓寒，凄其极目甚穷边。","黑尘犹暗新焦土，青日无光老晦天。","花凤逢春谁借景，杜鹃怀古自啼年。","吾今且忍须臾死，得见升平或有缘。"]},{"t":"二月十日送女清出适还次韵弟观代主留客","f":"五言律诗","c":["弟胡为自专，宴客数朝连。","敢越庖中俎，甘安肋上拳。","满腔虚醉饱，一段恶姻缘。","事过姑休问，风流记剡川。"]},{"t":"二月四日梅山弟留饮","f":"七言律诗","c":["醉中咄咄向空书，开眼犹能傲薄夫。","多事光阴存社栎，十年筋力老园芜。","籓篱吾道难为党，衣食诸人未信儒。","怀抱海深姑寄酒，习家池上不同途。"]},{"t":"儿侄辈为燕老集石秀叔以诗来和之二首 其二","f":"七言律诗","c":["白发扶携绿发迎，今为何日自欢声。","任供觞豆人情便，存古门庭俗眼惊。","寿语相期滋我愧，醉吟多感有儿赓。","但令里曲皆知孝，此酒何如考叔羹。"]},{"t":"儿侄辈为燕老集石秀叔以诗来和之二首 其一","f":"七言律诗","c":["身是书中老仆童，布衣不溯马头风。","虽无二顷资穷巷，犹有三峰著睡翁。","虚室漫留庄叟白，新诗忽见相州红。","危时流俗滔滔去，铁石心肠独我同。"]},{"t":"入京到西渡","f":"七言律诗","c":["昨宵北渡今西渡，系是离家第二宵。","诗伴风流勤犯驿，棹郎醉饱健迎潮。","丈亭浦上邻州接，笔架峰迷故里遥。","得意归来期可数，榴花如火照高标。"]},{"t":"入城似吴竹溪","f":"五言律诗","c":["投眠方丈室，为趁午潮差。","父执子爱我，客身心是家。","夜床安纸帐，晓枕梦梅花。","早作临溪别，此情天共涯。"]},{"t":"八句呈董稼山","f":"七言律诗","c":["楼阁高虚压翠微，诗囊酒担答春晖。","山环水抱花相映，天阔云开鹤自飞。","已有新阴共醉卧，何妨清话放迟归。","浮生难得如今日，回首人间万事非。"]},{"t":"十一月八日浑家避难周姓家终夜以榾柮火为禦寒之具","f":"七言律诗","c":["兽炭银山醉梦乡，何如榾柮地炉装。","微烟暖火权春燠，错节盘根傲夜长。","夙许孤寒陪暖席，不将光燄买烘堂。","风饕雪虐天昏黑，独占山家一脉阳。"]},{"t":"十月九日醉中二首 其二","f":"七言律诗","c":["人生欲满十分难，得七分安便是安。","鸟信天公终不死，□于云路本来宽。","须知老眼今如古，肯徇时情暖换寒。","说与儿曹能解意，相看一笑倚阑干。"]},{"t":"十月九日醉中二首 其一","f":"七言律诗","c":["八十二年真过分，两三閒屋漫偷安。","家人病退药方熟，儿子归来酒量宽。","祇把诗书供日用，不知宇宙有风寒。","开门但放溪山入，心本无他谁得干。"]},{"t":"十月十二日到慈云见去岁与龄叟诗因次韵","f":"七言律诗","c":["短筇敲路又投西，满眼皆诗不用题。","风撼材声如海怒，天铺雪意放云低。","自怜白发貂裘敝，欲借红炉纸帐栖。","记取年年此时节，两翁一醉笑扶携。"]},{"t":"又用韵示长儿","f":"七言律诗","c":["向来枯卉亦生芝，种学才深可瑞时。","语海方知蜗井浅，培风当使翼云垂。","可能任运如彭泽，也要名家似蜀眉。","理义本来非外铄，自求两字盍观颐。"]},{"t":"又似前人","f":"七言律诗","c":["薄俗交朋赴字斜，可人一见祇惊嗟。","心凭实地应多事，诗引清风归一家。","休看马头秋后叶，自培门里岁寒花。","何时相接从容步，遍历山巅与水涯。"]},{"t":"又次前韵","f":"七言律诗","c":["吁嗟天数不人由，举目江河万里愁。","为厉可无忠义鬼，觅封忍见笑谈侯。","功名只作无时看，气节须从险处留。","归去来辞非浪赋，曾知此老此心不。"]},{"t":"又次韵前人见示","f":"七言律诗","c":["世事纷纷乱似丝，放教公道总堪诗。","三年仁政从头去，百里人心是己知。","脉络相关真为国，毫釐不便甚捐肌。","残生何幸身亲见，也拟公堂举寿卮。"]},{"t":"又自用韵","f":"五言律诗","c":["泛泛一风舟，谁与管去留。","儿翁忘市井，女友隔河洲。","聊尔诗还债，从他笑有仇。","山林原自好，明日得归不。"]},{"t":"万寿寺主僧圆鉴留酒醉中","f":"五言律诗","c":["人世一沤浮，时光如瞬流。","相违十年久，偶见两心稠。","法嗣惊初意，香厨出异羞。","那知年到此，不枉少迟留。"]},{"t":"三井","f":"七言律诗","c":["两崖削铁上擎空，下有灵潭与井同。","龙出世时磐石透，水无底处洞天通。","馀波喷作雷霆怒，大旱腾为霖雨功。","兄弟相携看奇迹，脚跟牢立崄巇中。"]},{"t":"三月二十五日醵饮于西峰寺分韵得因字","f":"七言律诗","c":["牢穿不借踏青晨，信与林泉有夙因。","忙里偶成真率会，醉来不省乱离身。","归途西岭何妨晚，吹雨南风正送春。","烧笋煮茶须再到，一山古意要诗人。"]},{"t":"三月五日过云南竺湘家旧寓南轩怀朝儿","f":"七言律诗","c":["忆昨携儿寄小轩，儿今何在小轩存。","唤爹若有褰裳语，恋母犹多泪席痕。","两树桃花飞痛血，一山松影护游魂。","销凝良久忽如见，我与同归家处村。"]},{"t":"三月晦日同弟观侄津往宝幢哭刑部伯求弟道从茅山泊东林寺弟观有诗三首因次韵 其一 东林寺","f":"五言律诗","c":["投憩得幽寺，便忘行路遥。","竹边流水过，门外好山朝。","金相已流土，海音无复潮。","池檐立良久，老衲忽相邀。"]},{"t":"三月晦日同弟观侄津往宝幢哭刑部伯求弟道从茅山泊东林寺弟观有诗三首因次韵 其二 寺前即事","f":"五言律诗","c":["劫火不飞处，便如仙洞源。","载秧交野艇，卖笋到僧门。","潮水河分港，南风雨暗村。","家山百里外，回首已黄昏。"]},{"t":"三月晦日同弟观侄津往宝幢哭刑部伯求弟道从茅山泊东林寺弟观有诗三首因次韵 其三 坐雨","f":"五言律诗","c":["山泉今已矣，开落梦中花。","欲哭青松墓，却留黄檗家。","眼花飞作练，心事苦如茶。","造物故相阻，雨阴殊未涯。"]},{"t":"三次书怀","f":"七言律诗","c":["默察天翻地覆由，寸心无处著私愁。","忠唐不复瞻双庙，误汉皆知罪五侯。","牧马入南飞浙水，狩车遵北感陈留。","山川满目花如旧，邂逅春风可问不。"]},{"t":"上巳日同弟观张子开会内弟贝端甫家","f":"七言律诗","c":["村环十里即朱陈，时节过从气谊真。","酒味同甘山脉水，韭香一洗俗饕尘。","云南近日偶无事，天下几人知此春。","相对无言无尽意，不将桃李著精神。"]},{"t":"上乘展墓示子侄","f":"七言律诗","c":["吾行荷谢老天公，不放南来送雨风。","筇杖步前皆雅兴，梅花香底欠诗工。","尘埃辟易青山外，邱垄凄凉落照中。","一片初心分付处，儿孙他日记衰翁。"]},{"t":"与天宁寺主僧云岫对坐偶成","f":"五言律诗","c":["潇潇风雨里，得得又开门。","两榻蕙兰壁，半檐花竹村。","鸣蛙藏绿暗，归翼带黄昏。","此景少人会，相看付不言。"]},{"t":"与延庆老若圭游雪窦杖锡二首 其二","f":"七言律诗","c":["有意西游万玉峰，往来何事太匆匆。","知心能几片云外，回首应多明月中。","争供粟泥怀太白，终留梨实待兴公。","从今若枉诗相问，我住丹霞水竹丛。"]},{"t":"与延庆老若圭游雪窦杖锡二首 其一","f":"七言律诗","c":["坐断青莲七宝池，又携铁锡踏嵚崎。","一千丈雪与心照，二十里云随步飞。","崖壁遍留吟墨迹，樵刍争看袒红衣。","山林湖海本无二，处处风光属指挥。"]},{"t":"与弟观侄津哭伯求弟道茅山泊东林寺坐雨","f":"七言律诗","c":["西来本自趁晴天，雨卧东林日似年。","百念已成沈水石，一行真坐逆滩船。","何妨华鄂添诗集，暂与阇黎结饭缘。","决意明朝向东去，山堂未到已潸然。"]},{"t":"与单君范坐凝光亭","f":"五言律诗","c":["危世见交情，相逢坐小亭。","平看二麦秀，虚受万山青。","往事酒俱醉，可人诗自醒。","悠悠一俯仰，白鸟入冥冥。"]},{"t":"与龄叟","f":"五言律诗","c":["几年西崦寺，门藓路交藤。","龙象开禅席，钟鱼张法镫。","领徒耕趁雨，对客句裁冰。","我亦相忘者，慈云得屡登。"]},{"t":"乡人为予再赏凤花求赋","f":"七言律诗","c":["朝阳鸣处发天和，化作灵根植宝坡。","翠脊双飞供衬色，血诚百喙染芳窠。","仪韶难赴风云会，任数何妨岁月多。","翼翼自珍无一语，暗听游客赋卷阿。"]},{"t":"女兄归萧氏夫死誓守柏舟郡闻于朝赐旌表褒节","f":"七言律诗","c":["终身坚白表重阍，一粹真如玉不痕。","能使齐侯归吊室，自应沛相奏题门。","青天有眼临霜节，黄壤知心妥夜魂。","不见鄞江八行史，叶夫人德长儿孙。"]},{"t":"山人送桧植于当门偶成","f":"七言律诗","c":["山人知我岁寒情，十里移来老眼醒。","凿破苍苔方丈地，种为门户四时青。","春寒亦自雪霜意，世变从他风雨腥。","牢立本根须畅茂，不施巧结看真形。"]},{"t":"山甫用前韵留别因又次韵送行","f":"七言律诗","c":["二十年来一见悭，好风吹到小丹山。","心交融畅醒如醉，诗话绸缪忙亦閒。","村况非今非古处，花时半雨半晴间。","君今更欲寻僧去，知有吟边债未还。"]},{"t":"山居避难六首 其六","f":"五言律诗","c":["人生有如梦，世变亦浮沤。","无有悟双遣，穷通归四休。","终期风日美，不见雪霜愁。","此意因相谂，聊宽无益忧。"]},{"t":"山居避难六首 其五","f":"五言律诗","c":["避地托山翁，归心亦欲东。","西村明骑火，北渡撼兵风。","抖擞尘衣黑，摩挲泪眼红。","何如且深隐，苟活老光鸿。"]},{"t":"山居避难六首 其四","f":"五言律诗","c":["患难合扶携，临危路各迷。","传闻妻奔北，邂逅子随西。","心悼惊雷燕，身寒立雨鸡。","明朝问家事，空壁雪风凄。"]},{"t":"山居避难六首 其三","f":"五言律诗","c":["宦游二十载，时异即东还。","勇弃斗升给，本无分寸攀。","家贫空妇巧，学废重时顽。","平世已无况，况巢松竹关。"]},{"t":"山居避难六首 其二","f":"五言律诗","c":["并刀越砥磨，天奈北风何。","到处闻流杵，何时报止戈。","逃藏愁木栅，沦落泣毬窝。","多少岩阿□，真成病伏波。"]},{"t":"山居避难六首 其一","f":"五言律诗","c":["三十六风轮，清磨万古人。","军兴山胜市，岁歉富齐贫。","破絮身饶垢，乾粮舌费津。","吾生不足问，世事入长颦。"]},{"t":"山家即事","f":"五言律诗","c":["逃难走山巅，如何要顺便。","食艰蔬胜肉，衣薄炭输绵。","深静初心见，高虚远目鲜。","沈思亦自好，写景欠龙眠。"]},{"t":"山家即事","f":"五言律诗","c":["小筑山之下，林泉景自成。","閒花随付分，啼鸟本无情。","日暮岭云合，雨馀溪水清。","相逢是樵客，堪与话平生。"]},{"t":"中和节寓山庵","f":"七言律诗","c":["小庵亦是小桃源，时事方难住更便。","啼鸟落花忘客主，青山流水见因缘。","得过一日是一日，浪说百年谁百年。","分付妻儿更深避，扫岩趺坐学枯禅。"]},{"t":"丹山主者恭雪航年七十馀清苦善吟八句以似","f":"五言律诗","c":["本是住林深，浮云载出林。","蹒跚多病脚，邂逅十年心。","破鼓饥甘饭，残镫老醒吟。","我来相访外，梅竹是知音。"]},{"t":"丹山酒边","f":"五言律诗","c":["衰老受晴光，相携到上方。","意浓忘酒薄，话美夺尘忙。","天竹静逾媚，溪梅初有香。","危时正多事，半日太平乡。"]},{"t":"为龄叟作","f":"七言律诗","c":["多年坐镇翠微西，钟鼓声中好品题。","见大不嫌山寺小，立高应笑世人低。","扫莓苔地皆新筑，倚竹梅云是退栖。","最与老天相狎处，无边风月省提携。"]},{"t":"书于灵济方丈","f":"五言律诗","c":["信步领儿行，又来天尽堂。","老衰凭酒健，春好得诗香。","花柳年年事，江山处处乡。","拍阑一相笑，白鸟入微茫。"]},{"t":"云西已矣江东漕司绣春园柱閒诗尚存因次韵以写感云","f":"七言律诗","c":["柳边桃杏竹边梅，尽是先生手自栽。","旧事已随春梦断，新愁偏入老怀来。","空将满柱留题看，无复当花画册开。","试上层台望秦望，乡心禁得杜鹃催。"]},{"t":"元夕风雨","f":"五言律诗","c":["明日又元日，村祠一鬨人。","溪山浑是雨，镫火若为春。","忍见饥成鬼，痴将饱望神。","谁知生意处，官好自忧民。"]},{"t":"元夕醉梅山弟家 其二","f":"七言律诗","c":["为吾大患为吾身，假合将来认作真。","乌兔有谁相与老，燕莺于我已非春。","再生未死客中客，万事无闻人外人。","独有梅花尚知己，不妨一醉且同尘。"]},{"t":"元夕醉梅山弟家 其一","f":"七言律诗","c":["行年八十病馀身，梅坞留连率见真。","花到诗家方吐气，酒无菜饤不成春。","世情风雨妨归路，古道山林有主人。","珍重此时相得处，弟兄门外是浮尘。"]},{"t":"公棠溪次待舅氏竺九成舟偶成","f":"五言律诗","c":["驻马古溪头，期舟不见舟。","未知来否的，难决坐行谋。","滩远宽飞鹭，波平稳泛鸥。","功名在何处，到此两悠悠。"]},{"t":"六月六日倪■庵坐雨","f":"七言律诗","c":["山外黄尘不到门，南风松竹翠纷纷。","暗中有虎村嗥合，夜半闻鸡老睡分。","带得儿来同坐雨，飞归家去欲排云。","收书忽报今朝喜，病女加餐药奏勋。"]},{"t":"六里桥","f":"五言律诗","c":["拒霜红蓼丛，两岸递迎逢。","风雨日易夜，江湖秋似冬。","纵观心浩荡，无事梦从容。","不问程途远，诗情节节浓。"]},{"t":"壬午九日有感","f":"七言律诗","c":["修茂堂中九日杯，今年无复寿兄来。","把萸空感同看会，插菊难教一笑开。","不使犬鸡当厄去，却闻鸿雁送声哀。","浮生忽忽何须感，荒草牛山戏马台。"]},{"t":"天台徐德源许以谷应借","f":"七言律诗","c":["枯淡生涯寄草莱，短供不给甑尘埃。","吾徒例有绝粮事，世俗何从索米来。","邂逅指囷如鲁肃，分明流饭自天台。","不将乞字书为帖，拙语聊干一笑开。"]},{"t":"日峰庵","f":"五言律诗","c":["便道得幽寻，清风引入深。","庵依山石脚，僧说老岩心。","到处鬼无墓，此山松独林。","人生竟何事，搔首立青阴。"]},{"t":"王得淦次子侑生日求诗","f":"七言律诗","c":["梅窗生得宁馨儿，乳腹方离气已奇。","傅就外居来岁事，学从小入去年时。","擅三元美家谁继，有二郎贤父自知。","可是耄夫虚赞祝，向来功业是人为。"]},{"t":"见雪","f":"七言律诗","c":["冯夷老手妙庄严，一色工夫一夜添。","统捲山河还太极，平抛珠玉到穷阎。","瘦吟相谂梅寒苦，渴饮何妨秫冻甜。","黄竹方哀籴方涌，幸犹三白是丰占。"]},{"t":"见童志道旧居已非有感","f":"五言律诗","c":["人亡屋亦非，世事已堪悲。","遗树老于我，故山春为谁。","论文归一梦，闭眼立多时。","默默无言处，东风知不知。"]},{"t":"长儿吉初生日以四十字示之","f":"五言律诗","c":["吾年五十五，汝生方九年。","虽知得子晚，亦拟寿家传。","立己要庄重，存心无躁偏。","人皆可向上，从否勿归天。"]},{"t":"长至日山家偶成","f":"七言律诗","c":["畴昔随班舞御香，如今忍冻坐山房。","台云谁取书黄瑞，宫日空舒刺绣光。","懒把酒杯心自醉，閒攲肱枕意何长。","晚窗闭眼消详易，赖有生生不断肠。"]},{"t":"长桥望湖","f":"七言律诗","c":["太湖缺处束为桥，总把吴中景物包。","去百里閒山独立，跨三州地水平交。","古亭休说曾垂钓，长剑何妨更斩蛟。","欲觅鸱夷无处所，如今祇自网船抛。"]},{"t":"长孺以新生子求名命曰相儿","f":"五言律诗","c":["有女谐良偶，承宗在嫡儿。","馆甥才匝岁，宅相果如期。","脉发慈溪正，胞成江夏奇。","咳名应会得，乳口见呕咿。"]},{"t":"长孺因吾二诗有负米分邻之语因又次韵饯其归二首 其二","f":"七言律诗","c":["纷纷薄俗事轻唇，自喜衰年德有邻。","危世孤儿华发母，归舟百里碧波春。","不因噬指感怀切，肯学呕心搜句新。","娱舞慈庭应细说，丹山笋蕨正宜人。"]},{"t":"长孺因吾二诗有负米分邻之语因又次韵饯其归二首 其一","f":"七言律诗","c":["声气相投玉应金，花閒话到翠成阴。","一清门户无同脉，万古诗书可立心。","母子要知乌哺反，夫妻应感白头吟。","若言相谂早须觉，难得青春长似今。"]},{"t":"丙子丁丑年避难南山之西坑今春投北山两雪窦閒其地名适与前同因记以八句","f":"五言律诗","c":["西坑曾避难，今又一西坑。","十有四年梦，两番多事惊。","天乎存老息，地亦定前名。","何动不关命，怡然心气平。"]},{"t":"丙戌十一月十六日迎孙试周八句","f":"七言律诗","c":["杏林深处长孙枝，春意烘堂看试儿。","脊硬不移匍匐手，语迟厚养粹凝姿。","喜开三世瑶环瑞，满望重闱白发慈。","与汝家传双色笔，文章得力岂无时。"]},{"t":"丙戌五月朔閒坐偶成","f":"七言律诗","c":["石火光中见岁华，溪云深处寄生涯。","诗书屋下无嬉具，桑竹窗前有美花。","拗境日增多活愧，嚣尘天与一贫遮。","乾坤自隘乡邻好，犹得开门守故家。"]},{"t":"代天府曾安抚鹿鸣宴诗","f":"七言律诗","c":["笙簧声合隘春风，春在江梅第一丛。","月旦姓名光上国，日边步武便南宫。","看花自是长安客，对客当如横浦翁。","杯酒殷勤相属处，峥嵘头角已争雄。"]},{"t":"代吴景年次韵净慈寺主僧頔上人二首 其二","f":"七言律诗","c":["远公陶陆成千古，谁复相从过虎溪。","西隐老师虽有约，北山俗驾似难齐。","诗来日午双瞳醒，句出天心万象低。","时课家僮修茗供，松风清处坐分题。"]},{"t":"代吴景年次韵净慈寺主僧頔上人二首 其一","f":"七言律诗","c":["乌驱兔迫一衰翁，始信浮生总是空。","拈掇琴书终日事，依栖梅竹百年丛。","无官不用忧三黜，安分何劳送五穷。","咫尺上方钟鼓地，从师学佛便须躬。"]},{"t":"代京尹吴山云益雪应贺庙堂二首 其二","f":"七言律诗","c":["非才承乏尹瑶京，何幸亲逢造化成。","凝固地腴丰岁事，均调天气寿民生。","春归休念采薇戍，夜捷已闻垂瓠城。","方信太平元有象，九街箫鼓合欢声。"]},{"t":"代京尹吴山云益雪应贺庙堂二首 其一","f":"七言律诗","c":["安排寒事做年华，老手薇垣第一家。","神女先驰行雨旆，冯夷随剪舞风花。","万尘并纳真平等，一色横陈绝点瑕。","养乐堂前清赏处，贺班方退紫宸衙。"]},{"t":"代前人次韵赵县尉即席诗","f":"七言律诗","c":["旧来曾此摄雷封，勉策驽鞭愧罔功。","自分依莲游绿水，岂期沿檄又秋风。","今来视昔还多事，我亦无他祇一中。","此去未知能淑后，时知石药赖明公。"]},{"t":"代浦城权县赵节推鹿鸣宴诗","f":"七言律诗","c":["潜藩岁贡素多才，捷报欢声沸似雷。","南浦士流新姓字，西山夫子旧胚胎。","登荣仙籍香浮桂，得意春魁信在梅。","此去天衢齐纵靶，代庖祗饯幸重来。"]},{"t":"兄弟醵饮访雪航次弟观韵二首 其一","f":"七言律诗","c":["天女多年为散花，晚年来此寄年华。","贫因好客甘如荠，诗解醒人苦似茶。","入室漫为云作主，开窗惟许月通家。","有时得句忙题处，满壁淋漓字湿鸦。"]},{"t":"兄弟醵饮访雪航次弟观韵二首 其二","f":"七言律诗","c":["梦断天边飞佩霞，短筇松路趁溪斜。","归鸦山外烟如画，过雁云閒雪欲花。","跌岩琴书谁我辈，承平钟鼓自僧家。","从今载酒须同醉，兄已头童弟发华。"]},{"t":"出门寄弟睹子得","f":"七言律诗","c":["半年腿卧近方仁，一出门来拂濯身。","交十月天村景好，连三日雨晚晴新。","青山无语自知我，黄叶是愁还可人。","谁信幽居便忘世，渔樵亦自有经纶。"]},{"t":"出剡北门道中","f":"七言律诗","c":["晴日烘冬扫宿阴，篮舆伊轧出山深。","田夫忍冻妆旗帐，学子忘劳走佩衿。","三载一馀多少过，万人相送独何心。","新官便好观风俗，莫道无人识古琴。"]},{"t":"卢竹溪得处士号邑尹有诗卢以其唱及其自和来求余次韵","f":"楚辞体","c":["梦破邯郸百念齐，长汀西畔半分溪。","护符清出黄冠品，承命有加紫诏泥。","径捷更谁疑晚节，山居有客侈新题。","老吾亦是三峰裔，何幸相逢有子兮。"]},{"t":"四月八日携子侄到上乘偶成","f":"七言律诗","c":["白首犹堪数里行，相过一笑见山堂。","残僧门径静于夜，新夏林塘暖自凉。","且借吟床娱半日，何妨归笠戴斜阳。","我来岂敢辞筋力，先陇松楸倚寺旁。"]},{"t":"四月三日与家人小酌转官毬花因成八句略为花吐气也","f":"五言律诗","c":["红芳销歇后，天质最分明。","剪衬青云薄，团成白雪轻。","官途荣进取，时样妄推评。","本色相看处，幽窗不世情。"]},{"t":"四月五日后圃酴醾芍药侍郎三花盛开醉中成三咏 其一","f":"五言律诗","c":["酴醾忽尽花，春与夏交加。","顷刻当千日，风流能几家。","香丛迷粉蝶，曲蔓走青蛇。","火急要清赏，可人归未邪。"]},{"t":"四月五日后圃酴醾芍药侍郎三花盛开醉中成三咏 其二","f":"五言律诗","c":["芍药又将开，那堪夜雨催。","密铺萱草衬，巧傍牡丹栽。","省砌休思著，扬州曾看来。","芳菲概如许，俯仰亦悠哉。"]},{"t":"四月朔日乡饮于邑董氏之依绿亭口占","f":"七言律诗","c":["道义为乡自不同，肯随流俗唾衰翁。","高谈惊散洗红雨，清饮唤回依绿风。","直欲鸢鱼相上下，那知乌兔有西东。","得閒不乐真堪笑，金谷平泉总是空。"]},{"t":"四次寄意","f":"七言律诗","c":["正大从来不径由，穷崖今却伴猿愁。","栖栖宇内知师孔，吃吃人閒爱说侯。","昨夜撞钟搜句到，他年笼壁把名留。","崆峒麦熟关时事，此意还曾入咏不。"]},{"t":"外甥黄阿相生日","f":"七言律诗","c":["湖山聚秀系斯文，汝更峥嵘瑞户门。","嵩里是人誇宅相，慈溪之后有曾孙。","书声自可怡重庆，家学何妨涨一源。","远大相期吾耄矣，莫将苦语等閒言。"]},{"t":"戊寅三月十一日为桑麦说苦","f":"七言律诗","c":["一年景象在春光，底事今年春反常。","四十日来无点雨，二三月里却多霜。","麦苗病燥饭亏料，桑叶死寒蚕绝粮。","天下苍生不堪命，但看人事即阴阳。"]},{"t":"旦起诵邵尧夫诗","f":"七言律诗","c":["二十年前尘路忙，如今都住寂寥乡。","梅花时节溪山好，菜粥人家门户香。","否往泰来天外事，早眠晏起枕中方。","案头只有尧夫集，参得透时滋味长。"]},{"t":"正月二十四日到梅山二首 其二","f":"五言律诗","c":["梅花草屋边，好景得天然。","梦境閒为上，归途倦莫前。","无情推醉石，有分是流年。","已约重来日，白云留醉眠。"]},{"t":"正月二十四日到梅山二首 其一","f":"五言律诗","c":["困来禁不住，一动亦悠然。","家事青山外，春心白发前。","逢人相问岁，为客又开年。","得醉梅花下，何妨就石眠。"]},{"t":"正月五日访王韦轩知府东坞真诏道中","f":"七言律诗","c":["晴光欲雪做新元，访旧西来第一番。","十五里行千曲路，两三处见数家村。","山培浮土为田肉，涧束湍流有石痕。","安稳不知危世事，更从何处觅桃源。"]},{"t":"正月四日到张车偶成","f":"七言律诗","c":["晴行半日到张车，石路崎岖趁水斜。","一窟山中成草市，数株松下见梅花。","居民尽老他无事，就土为生自有涯。","谁料如今同沸鼎，不时飞马涨尘沙。"]},{"t":"正月晦日与弟观对酌","f":"五言律诗","c":["聚散等风沙，相知要当家。","弟兄窗下酒，世俗眼前花。","隐去方为福，贫驱未有涯。","明朝吉凶事，分付与昏鸦。"]},{"t":"用长儿韵谢黄长孺酒","f":"五言律诗","c":["薄俗方沈溺，亲情自酌斟。","雨声书屋冷，春意酒杯深。","危世不多话，醉中时一吟。","明年如老健，此会得重寻。"]},{"t":"用长孺七夕韵","f":"七言律诗","c":["炳炳双星从古然，滔滔多话到今传。","渺茫河上曾无事，醉梦人閒自并缘。","妄不易祛姑立我，巧如可乞岂为天。","痴儿甘受三年诈，独有崔生此话贤。"]},{"t":"用帅初韵谢其寿我之意","f":"七言律诗","c":["锦云忽把老瞳遮，寿语何为及我家。","怕说庚寅赋湘芷，漫书甲子谱陶花。","长途交骛鼠为虎，孤迹偷生蛇放蟆。","人世到今何足问，桑榆况已日西斜。"]},{"t":"用弟观韵二首 其二","f":"七言律诗","c":["粉儿乳子等蓬麻，书种精神见始哑。","自分閒居培玉树，无心劳役谶金沙。","如龙当有腾高日，何恙能侵积庆家。","乳哺薄乖随勿药，番成点浪□涂鸦。"]},{"t":"用弟观韵二首 其一","f":"七言律诗","c":["住世光阴晓日霜，浮生谁弱又谁强。","干戈时节贫差稳，诗礼人家话亦香。","何用移文来北陇，可能把酒博西凉。","妻无愠见儿堪教，门外从他沸一铛。"]},{"t":"用前韵记梦中所感","f":"七言律诗","c":["风引归舟远翠蓬，转头三见柳花风。","伤心殆尽王摩诘，痛哭真成贾太中。","尚有鬼神知夜问，谁知兄弟坐天穷。","此时此意无人会，放读离骚太乙东。"]},{"t":"用前韵似龄叟","f":"七言律诗","c":["早岁雄心撼不周，晚年归契老禅游。","肯除酒戒容元亮，欲答梅诗愧子由。","隐几云山长在眼，出门风雪又回头。","元宵有约慈云阁，镫火能无感旧愁。"]},{"t":"用前韵自述","f":"七言律诗","c":["忆昔微官玷瞽宗，归来十载坐山穷。","有家却似髡头释，无齿真成吮乳翁。","□□□清秦吉了，饿犹未死信天公。","馀生趯趯只如此，看取东坡赋二虫。"]},{"t":"用前韵呈晓村","f":"五言律诗","c":["溪山两相望，只隔五长亭。","一见坐联日，高谈气拂星。","好宾知络秀，兼仆困樵青。","此会受多益，归途杖可铭。"]},{"t":"用前韵送酒与约斋","f":"五言律诗","c":["人生以类合，圆木不投方。","家话太平旧，山盟晚节香。","百罹心易足，一醉味何长。","但得静中乐，村村皆洛阳。"]},{"t":"用前韵答龄叟见寄","f":"五言律诗","c":["草堂存老我，茅屋著而翁。","门户两家异，溪山一趣同。","夜炉榾柮火，春阁杏花风。","何惜盟吟社，浮尘付过鸿。"]},{"t":"用梅山别诸贤韵","f":"五言律诗","c":["世变事难必，天伦爱自深。","醉醒皆外物，甘苦共初心。","倦翼山招返，寒林风为吟。","何当长聚首，衰境况侵寻。"]},{"t":"用戴帅初韵寄孙常州","f":"七言律诗","c":["溪绕山围杨柳遮，战蜗国里退閒家。","儿孙满眼堂万卷，宾客多贤馆五花。","立脚东皋看倦鸟，回头温水笑跳蟆。","相知惟有诗相寄，便羽一封三印斜。"]},{"t":"甲戌考类试院呈同官","f":"七言律诗","c":["天风吹散扑衣尘，奎壁光中预□文。","老眼可能私李豸，公朝正欲第刘蕡。","平生泾渭岂无见，暗室雷霆如有闻。","一雨快晴秋意好，预占太史奏祥云。"]},{"t":"白珽寄诗次韵见意","f":"五言律诗","c":["江干风雨别，君住我来回。","两地梦相觅，十年书一来。","字参老未到，诗放晚唐开。","直要吟成史，扫清尘世埃。"]},{"t":"示内","f":"五言律诗","c":["婚娶不在早，在此两相宜。","岂得人无妇，能如子者谁。","科名图我取，家务以身支。","要见看承处，颓然白发时。"]},{"t":"示王侑翁二首 其二","f":"五言律诗","c":["硕果生机在，从他剥五阴。","南山四时面，残屋百年心。","家薄有书种，客多成笑林。","要閒元自老，不在卜居深。"]},{"t":"示王侑翁二首 其一","f":"五言律诗","c":["垂髫已解吟，髣髴学何阴。","暗动梅窗喜，遥传桂种心。","染声毋市井，近拙要山林。","耄矣不成句，中閒意自深。"]},{"t":"示都儿学书","f":"七言律诗","c":["都子方知砚石亲，字虽小技盍留神。","鲁公米帖犹存古，王氏兰亭已失真。","莫事锋铓多巧锐，要令骨肉两停匀。","中心端正手圆活，此外无方可教人。"]},{"t":"示梅山弟八句","f":"七言律诗","c":["浮世蘧庐付一呀，诗书馀沥子孙家。","两池分受高低水，四岸量栽次第花。","笑傲溪山如故旧，招邀云月共生涯。","相逢数酌春风酒，不信人间有战蜗。"]},{"t":"次韵张子华见寄","f":"五言律诗","c":["老矣息林邱，平生不径由。","知心时一见，安分别无求。","寒卧死中活，荣华乐处忧。","世閒何限事，曾看过云不。"]},{"t":"次韵戴帅初除夕并寄弟观二首 其二","f":"七言律诗","c":["兄弟相依友在邻，又添一岁话情真。","梅花素入两年眼，椒酒难医百病身。","敝帚自珍从众笑，破皮非怪亦多嗔。","柴门一任风开闭，静看争春车马尘。"]},{"t":"次韵戴帅初除夕并寄弟观二首 其一","f":"七言律诗","c":["天如旋磨又今春，留得非才未死身。","浮世生来真逆旅，危时老去少同人。","俗情一夜分寒煖，道眼百年无旧新。","但恐明朝官事动，叫嚣隳突满乡邻。"]},{"t":"似仁泽宗芑","f":"五言律诗","c":["来访寄窗师，新田雨茗期。","凉生开酒量，香妙醒诗脾。","半日旧来话，古心他更谁。","要知梦非梦，试问两相知。"]},{"t":"似史和甫传清","f":"五言律诗","c":["翩翩鹤往还，高眼看尘寰。","家世崔卢上，风流晋宋閒。","开门种桃李，落笔动江山。","勋业时来做，青春赢得閒。"]},{"t":"似永固主僧惠福","f":"五言律诗","c":["偶来乘暇隙，又过古禅林。","白日钟鱼外，清风竹树阴。","无言自有趣，得句亦何心。","相见不相问，老僧知我深。"]},{"t":"似告成寺主僧蟾秋海","f":"七言律诗","c":["出宫墙外步冬暄，转憩黄花翠竹边。","一笑偈言非本色，相留清供亦前缘。","土酥饤洁昏眵醒，汤乳包香老齿便。","祇恐醉陶终爱酒，难陪惠远共修莲。"]},{"t":"似李德昌州判","f":"七言律诗","c":["借重东南官府新，与秋高洁更春温。","公心知寄黄堂印，信令如开綵棒门。","纯用诗书中古味，乐闻名利外陈言。","耄夫也为乡民贺，硬忍须臾一出村。"]},{"t":"似法椿长老","f":"七言律诗","c":["山林有福足慈云，一耐中閒百废新。","诗榻话香来雅伴，斋钟声好撼禅邻。","红颜药力如平日，青眼梅花又小春。","欲赞法身安稳处，年年松竹长精神。"]},{"t":"似法椿龄叟","f":"五言律诗","c":["人生契合处，信是宿因缘。","坐到无言外，参成有佛前。","好山非昨日，啼鸟又今年。","带得醉归去，醒时风满天。"]},{"t":"似范景山","f":"五言律诗","c":["我辈岂池蛟，飞腾此一交。","天门惊路梗，冰港笑舟胶。","甘甚新薇蕨，依然故草茅。","从今门外事，洗耳学由巢。"]},{"t":"似郑宗平","f":"七言律诗","c":["幕府新开紫气临，红莲绿水照初心。","宦游受用家庭训，公退寻盟湖海吟。","傍塔山居真吏隐，酌碑潭饮当官箴。","自矜出谷儿嬉老，一面春风得最深。"]},{"t":"似星同知","f":"七言律诗","c":["通守鱼符委任隆，规模新处见新功。","来从北斗光躔下，坐治南山紫翠中。","载路政声如药石，契天心画在屏风。","深深到底清相映，一派碑潭水最公。"]},{"t":"再用前韵谢吴竹修","f":"五言律诗","c":["秃髡归阳羡，仙髯卧古藤。","前贤成昨梦，后辈嗣谁镫。","倾盖欣如故，吟坛得共登。","春风吹相聚，聊此寄韦冰。"]},{"t":"吊单方庵墓","f":"五言律诗","c":["方庵居士死，归骨白云根。","霜暑三年别，风流万古存。","月梁空夜梦，宿草长春痕。","松底幽兰发，清香是梦魂。"]},{"t":"同范景山到城西墺游鹿苑寺","f":"七言律诗","c":["片帆带月趁潮行，晓及三江作住程。","上冢偶随庞老去，过溪忽见远公迎。","山疑无路亦多路，鸟独有声时一声。","幸自醉乡风唤醒，斜阳烟草旧花城。"]},{"t":"同赵景文到梅山弟家","f":"七言律诗","c":["脚力犹支一里閒，得闲便不记艰难。","可人本色山林屋，避世珍羞芋栗盘。","来往任教诗眼热，笑谈能化老身寒。","感怀棠棣诗章在，试把丝桐檃括弹。"]},{"t":"同离孙童蒙游净慈","f":"五言律诗","c":["三月第三日，又来游梵林。","醉言惊俗耳，贫趣契僧心。","犬吠落红外，鸟啼空翠阴。","一年最佳处，分付老龄吟。"]},{"t":"同袁通判游越中三首 其一 禹庙","f":"五言律诗","c":["舟行可十里，上岸即山林。","曲径抱深意，怪松传古音。","平生能几到，好处欲穷寻。","春鸟一声处，乡关又上心。"]},{"t":"同袁通判游越中三首 其三 赵节使稽山门外花园","f":"五言律诗","c":["前贤眼力到，占得此名区。","荒径百年树，虚堂三面湖。","檐阴来钓艇，花外起晴凫。","借问园中叟，主人曾到无。"]},{"t":"同袁通判游越中三首 其二 鸿禧观","f":"五言律诗","c":["停舟过桥去，两岸绿垂杨。","绕屋水为界，入门花满廊。","如今为道观，闻昔是书堂。","此意与谁说，春风湖渺茫。"]},{"t":"同黄东发提举游杖锡山","f":"七言律诗","c":["十八盘头翠碧函，参差檐栋倚岩崭。","桑根已换如来座，峰顶犹存太白岩。","地有粟泥堪当饭，山无松木独宜杉。","半天图画风尘外，我有新题居士衔。"]},{"t":"回家","f":"七言律诗","c":["为嫌客闷转还乡，到得还乡梦转长。","密友会疏心欲折，贫家事富担难当。","秋山有态忻新雨，风叶无名怨夕阳。","此景劝君评洎取，免教诗社报凄凉。"]},{"t":"因閒坐偶成韵谢黄虚谷","f":"七言律诗","c":["梦曾骑马踏京华，老矣盟鸥寄水涯。","回首故人多宿草，攒眉晚节自寒花。","南风漫把初心鼓，西日难将只手遮。","犹有穷吟谁管领，何时王翰作邻家。"]},{"t":"如岳上人求赋剡鹿苑寺一览阁","f":"七言律诗","c":["层檐危镇梵王宫，景物都归两碧瞳。","九万里风斯在下，三千世界本来空。","诗怀浩浩晴澜外，人事滔滔流水东。","凝伫移时还暝坐，胸中天地自玲珑。"]},{"t":"岁首戒子到外家展驾寄内弟竺少博","f":"七言律诗","c":["古俗流传重岁新，交相来往笃亲亲。","外家在望无十里，内表如今能几人。","筋力难施身已老，形骸不索意方真。","儿曹能拜何妨遣，要使绸缪百世春。"]},{"t":"收芋偶成","f":"七言律诗","c":["数窠岷紫破穷搜，珍重留为老齿羞。","粒饭如拳饶地力，糁羹得手擅风流。","家贫自盍勤多种，岁晚何当饱一收。","回首人閒剑炊米，谁知煨烬有炉头。"]},{"t":"次儿生日八句示之","f":"七言律诗","c":["祖心流庆我生儿，说与吾儿初诞时。","吉梦觉来珠蚌坼，喜声浮动玉麟知。","如今弱冠归妻后，此是平生进德基。","自有季方家样在，一门诗礼要扶持。"]},{"t":"次儿瀹以年字韵呈喜而又赋","f":"七言律诗","c":["一诗未足见儿贤，意气中閒颇蔼然。","忠厚人家宜有后，乱离时世始知天。","老怀信汝穷须达，俗眼从渠丑做妍。","培得根深花自茂，莫将今日看他年。"]},{"t":"次王得淦韵","f":"五言律诗","c":["浴出矮檐阴，披襟小雨侵。","坐凉三鼓漏，和梦一镫吟。","自分死中活，谁知升与沈。","明朝书局事，奔走岂初心。"]},{"t":"次吴竹修寄泽南洲韵","f":"七言律诗","c":["君客蓬堧偶滞留，我寻菊伴枉经由。","翠微轻失相逢笑，白发堪禁几别愁。","只为交情如管鲍，未能忘物似聃周。","何妨重约论文酒，尚有橙黄橘绿秋。"]},{"t":"次弟观二首呈雪航 其一","f":"五言律诗","c":["流俗方澜倒，禅心自铁顽。","人于诗信老，天与病全閒。","拄杖溪山曲，移尊雪月閒。","相逢多拙句，为我细修删。"]},{"t":"次弟观与龄叟诗韵","f":"七言律诗","c":["雪窦飞来一片云，寺门兴起总由身。","钟鱼饭众有今日，钲鼓粥神多信人。","两阁眼空风黑夜，四山手植雨清春。","我今亦是陶潜辈，三笑图中就写真。"]},{"t":"次弟观为陈子得纳妇别李亲家","f":"七言律诗","c":["马头姻缔热相寻，谁识清交旧绂簪。","泽底李无门望态，村中陈有世婚心。","别来得见百罹后，坐到忘言两意深。","醉里送君何所有，嚼梅花碎写成吟。"]},{"t":"次前人卜居得邻","f":"七言律诗","c":["买屋相依老翰林，满腔新意见新吟。","浮云仕宦四方志，明月家山千里心。","邻谊可曾分楚越，诗盟那有远何阴。","老夫亦忝桐乡籍，贺厦行须曳足音。"]},{"t":"次前人拉游南山借意道别","f":"七言律诗","c":["公与南山是夙知，三年对面肯轻离。","长汀明月催孤棹，广莫高风酹一卮。","采菊空怀忘辩意，有台须立太平基。","坐岩□处如追旧，尽取瑞峰留退思。"]},{"t":"次前人韵以寄","f":"七言律诗","c":["流俗谁能问故知，慇勤书信驿同驱。","古心地老天荒日，閒意风来月往时。","交一臂閒机尚失，隔千里外会难期。","从今要识相思瘦，认取青山槁木枝。"]},{"t":"次前韵与前人同舟自城归","f":"七言律诗","c":["夜泊南津梦岸斜，老来行役祇堪嗟。","满篷风露五更月，残梦溪山百里家。","蹴起睡奴催纤路，坐同吟伴说梅花。","此归又且深深住，澜倒中閒要见涯。"]},{"t":"次前韵与舅氏竺九成求芋","f":"五言律诗","c":["何处蹲鸱美，云南一望中。","角巾临晚岁，拙语寄西风。","喜报无乾鹊，缄回靳篆虫。","还诗元有例，盍与昔人同。"]},{"t":"次前韵示前人","f":"七言律诗","c":["人生不料有今年，知汝扶亲走翠巅。","动脚可能无陷阱，保身正合惧冰渊。","夷伤无奈明归地，坎险惟将心靠天。","岂意老躯几折臂，未能扃户日高眠。"]},{"t":"次前韵戏似","f":"七言律诗","c":["喜逢新岁带春回，四老过从贺泰来。","君若燕毛分次第，我当鹤发领徘徊。","忺怀爵跃空相望，弱脚蹒跚阻一陪。","传语诸贤任抛外，百年夫妇自衔杯。"]},{"t":"次前韵吴山甫解嘲","f":"七言律诗","c":["望春山下剡溪湄，穷处无聊甚系累。","竹会依然思二阮，苗凶行矣入三危。","枭声只盍闻而睡，蛇影堪期达者知。","试问流空千古月，过云妨得几何时。"]},{"t":"次前韵谢月窗兄见和","f":"七言律诗","c":["人得清閒便是仙，秋光堪画欠龙眠。","泻檐才歇催诗雨，入户惊飞落纸烟。","句与杜陵同中律，世无钟子莫知弦。","籁鸣机动聊相友，捧砚犹强武士贤。"]},{"t":"次前韵谢同楼诸公","f":"七言律诗","c":["凝香画阁昼闻铃，唤我真心十倍醒。","奋臂勇寻西学侣，回头挹谢北山灵。","京华是则薪炊桂，旅食何妨实剖萍。","此去功名如到手，也须伏阙疏延龄。"]},{"t":"次赵景文绝粮","f":"七言律诗","c":["赤峤归来似梦中，春风满面扫儒穷。","祇愁不祭鬼成馁，那问乏供儿哭空。","饥卧何妨专雪屋，清贫消得唤冰翁。","浮生总是閒烦恼，天已安排十二宫。"]},{"t":"次黄长孺元夕韵","f":"七言律诗","c":["流俗谁知运会元，逢场作戏逐时论。","梅花簪烛行呼野，竹叶装巾醉舞村。","幸是深山宽夜禁，苦无佳月破天昏。","鳌山盛事当年梦，老不禁寒早闭门。"]},{"t":"次韵义乌贾养晦元夕书怀","f":"七言律诗","c":["新得新晴纵夜游，纱笼喝道肯迟留。","风流买市皆如愿，雪艳歌筵总莫愁。","不放晴光半分过，亦知人世一沤浮。","星星镫火须臾事，何似长看素月流。"]},{"t":"次韵女淑寿兄诗","f":"七言律诗","c":["道韫生来亦谢芝，解吟今有寿兄时。","着行布字银钩细，镕意成辞金薤垂。","义气流行亲手足，笑风吹到老须眉。","自家儿女能如此，一味清甘足解颐。"]},{"t":"次韵子仓二首 其二","f":"七言律诗","c":["君学柯山我学家，相逢悃愊两无华。","有缘偶食金陵粟，连岁同听玉树花。","各占路头图展布，不随人口斗諠哗。","向来平实交相勉，笑杀粗心古押衙。"]},{"t":"次韵子仓二首 其一","f":"七言律诗","c":["清溪游倦又浮家，带雪来观上国华。","飞檄有声争致稿，通闺得荐已攒花。","立看云雨蛟龙起，坐笑春风鸟雀哗。","好向江湖忙著句，回头纶凤出南衙。"]},{"t":"次韵仁泽僧来见","f":"五言律诗","c":["嵩溪修竹下，一榻坐幽深。","时异交游少，年衰百病侵。","生涯成鸟啄，村景付猿吟。","惟有相从梦，时时到梵林。"]},{"t":"次韵内兄舒通叟太博寓云南僧舍","f":"七言律诗","c":["河海翻飞信有由，相逢莫学楚囚愁。","人方椎髻说苏子，天把布衣存武侯。","世变古今张与翕，人心造化去中留。","云南高处应看透，许得溪翁入坐不。"]},{"t":"次韵内侄竺稷并示诸儿","f":"五言律诗","c":["春首还相见，吾怀白与兄。","江湖关老梦，山野避新行。","危虑船迎浪，残生漏送更。","东风溪上路，欲别若为情。"]},{"t":"次韵内侄竺稷留别","f":"七言律诗","c":["外家忠厚世多才，挑辔相过一笑开。","珍重年光记亲戚，绵延义脉到云来。","后生要积为山篑，前事休论覆水杯。","榾柮炉头好情话，莫冲风雪便轻回。"]},{"t":"次韵天台陈榆收","f":"五言律诗","c":["世态自浮轻，犹存冷处盟。","功名随泡影，道义要权衡。","打破片云隔，来分半日清。","且须谋隐事，未问把天擎。"]},{"t":"次韵天宁僧宗芑见寄","f":"五言律诗","c":["新诗忽相问，知我有如君。","陶令早还里，少游终守坟。","犁锄聊自课，笔砚未全焚。","时放出门步，仰天看过云。"]},{"t":"次韵少野","f":"七言律诗","c":["古调难逢钟子期，近交祇数巳公诗。","家风自别閒相似，心事无涯话有时。","草木味中犹著我，荆榛丛里更同谁。","衰年如许会能几，俯仰悠悠云水知。"]},{"t":"次韵王圣传自叹","f":"七言律诗","c":["道义相从自一宗，世人扰扰等鸡虫。","桂坊素袭多文富，橘隐何忧五鬼穷。","宽以平田为日用，笑将逆境付天公。","何时王翰相邻住，樽酒论诗两醉翁。"]},{"t":"次韵王监叔","f":"七言律诗","c":["君家深似武陵源，又出云来旆影翻。","负笈肯忘鄞北里，彯缨长说海东门。","健收风月归谈麈，醉挽河江入酒樽。","回首溪山吾耄矣，笑盟知有几番温。"]},{"t":"次韵王监叔二首 其一","f":"五言律诗","c":["青山绿水乡，竹里喜还堂。","犬窦可曾警，雀罗何用张。","苦诗谁是甫，问字我非扬。","有感飞霞佩，相从老不忘。"]},{"t":"次韵王得淦和儿泌西山所作二首 其二","f":"五言律诗","c":["亲戚要绸缪，其来远有由。","溪山行可到，岁月去难留。","休问酒无有，但将诗应酬。","春光是堪处，不是少年游。"]},{"t":"次韵王得淦和儿泌西山所作二首 其一","f":"五言律诗","c":["门径不为深，溪山巧带襟。","老来无过计，贫极见初心。","儿漫煮饥字，甥能赓醉吟。","不羞狂脱帽，无发可胜簪。"]},{"t":"次韵长儿生日示诸弟","f":"七言律诗","c":["吾爱吾儿责望儿，终身实处看平时。","夫妻琴瑟方为顺，伯仲埙篪便是诗。","要向鲁邹中进步，先从曾闵上求知。","酒边见汝倾心句，不觉摇头笑脱颐。"]},{"t":"次韵东平赵孟益游北山寺","f":"五言律诗","c":["潇洒一僧关，钱家古墓山。","云多迷早晚，溪阔限忙閒。","斋鼓青龙麓，渔歌白鹭湾。","欲吟吟不尽，岩溜自潺潺。"]},{"t":"次韵东皋寺主僧知恭见寄","f":"五言律诗","c":["平地起丛林，工夫岁月深。","百吟三教髓，一饭十方心。","惯听人传说，閒将梦去寻。","书来足自慰，亦是老知音。"]},{"t":"次韵卢致远见示","f":"七言律诗","c":["新春欲洗旧氛埃，并竹寻溪试一来。","冻雨忽交疏霰下，严风不放寸云开。","主人雅量诗相住，老客归心梦亦催。","滑道何妨徐著步，袖中金薤不虚回。"]},{"t":"次韵卢致远祈雨喜应","f":"七言律诗","c":["四郊多少出云山，六月如何得雨悭。","天意茫茫知不外，秋成岌岌有无閒。","人非稼穑谁为命，职在蛟龙可听閒。","终藉精忱起灵蛰，鹤骖带得夜瓢还。"]},{"t":"次韵史芝田来访","f":"七言律诗","c":["珊然环佩下芝山，醉梦人閒醒眼看。","三世相家知有后，十分谦德似无官。","骚盟宽与江湖接，清气直将星斗干。","难得相逢容易别，因风时为劝加餐。"]},{"t":"次韵史芝崖","f":"五言律诗","c":["浮生真梦幻，看破已频频。","花柳春心古，乾坤世事新。","争芳多煖处，感旧独幽人。","宝重复珍重，清风明月身。"]},{"t":"次韵史猷父","f":"七言律诗","c":["西崦残晖薄首邱，与猿同啸鹤同游。","山林一出资惊笑，风雨多情管滞留。","前别忽来如再世，后期禁得又三秋。","湖天倘有相从分，为我何妨割半洲。"]},{"t":"次韵史猷父乡集","f":"七言律诗","c":["两贤主礼一般春，还是慈湖曲里人。","久旷忽行知世变，相逢交贺见情真。","发身清苦盟方暖，回首荣华迹总陈。","更看它年陪菜酒，耆英会后接芳尘。"]},{"t":"次韵四明孙常州","f":"七言律诗","c":["忽忽光阴日隙尘，回头十载两襟分。","听经偶枉真人驾，过首犹怀处士坟。","危世清风谁一面，青山啼鸟自相闻。","慇勤寄到新诗卷，奇字终须问子云。"]},{"t":"次韵帅初浙西回及得新居三首 其三","f":"七言律诗","c":["家有图书便不贫，一湾门径碧溪滨。","山林深密宜今世，梅竹婆娑似故人。","少闭柴门延野叟，多营菜圃慰脾神。","几年役役方休息，收放浑如一钓纶。"]},{"t":"次韵帅初浙西回及得新居三首 其二","f":"七言律诗","c":["自昔恒河可聚沙，今为何日更堪嗟。","未应绝物从孤竹，尚可依人住浣花。","疲俗交□□□□，□时仍重读书家。","老吾幸有相过便，尚得如蓬倚直麻。"]},{"t":"次韵帅初浙西回及得新居三首 其一","f":"七言律诗","c":["闻得胥江尚涨沙，往来虽便重嗟嗟。","旧游怕说铜驼棘，遗曲难听玉树花。","满目山川谁是客，无情天地若为家。","栖栖又入西峰下，踏破山鞋几两麻。"]},{"t":"次韵石秀叔","f":"五言律诗","c":["挥手世閒尘，忘言晋与秦。","溪山能住客，风雨始知人。","澹澹秋光趣，悠悠野鹤身。","相闻愿相见，倦脚走双轮。"]},{"t":"次韵石秀叔城归卜邻","f":"七言律诗","c":["从来热处易留人，孤负初心垫角巾。","盍与溪山酬素约，任将风月洗黄尘。","口犹有齿先尝乳，事付无言但饮醇。","见说明朝又东去，莫教虚梦觅诗邻。"]},{"t":"次韵石秀叔慈云逃席自解","f":"七言律诗","c":["山林幸自绝尘氛，旧事谁嗟散幅裙。","方外老交心似水，坐中高论气腾云。","杯盘引兴真相率，钟鼓催晨醉不闻。","但愿长留风月主，从今径造免移文。"]},{"t":"次韵石秀叔慈云避席自解","f":"七言律诗","c":["幽居便合洗城氛，清隐如何及妓裙。","横浦名为交佛日，眉山老自爱朝云。","逃筵觥罚宁甘受，隔壁钗声想暗闻。","色即是空曾记否，饶君百喙亦难文。"]},{"t":"次韵似前人","f":"七言律诗","c":["山居随意旋添成，截断人閒利欲腥。","兰茁不妨虚白屋，松苗如见旧毡青。","书痴面目唾亦笑，酒圣风流心自醒。","閒里光阴天下乐，谁知此处是思亭。"]},{"t":"次韵孙与之见寄","f":"五言律诗","c":["江山百里馀，相得肯相疏。","寄雁苦无便，遗鱼俄有书。","心能谦以下，义得兑之初。","耐久难忘处，我将铭陋居。"]},{"t":"次韵孙古岩冬景","f":"七言律诗","c":["腊天风景最无常，儿造颠狂亦有方。","将放雪飞连夜雨，欲留晴住一朝霜。","城头柳色吟边动，山曲梅花梦里香。","身在黄尘三尺外，静中无日不春光。"]},{"t":"次韵延庆僧惟巧山见赠","f":"五言律诗","c":["巧山元不巧，此处不容传。","意到头撞壁，吟香口有莲。","江山皆逆旅，风月独知贤。","世事如何说，相看一笑边。"]},{"t":"次韵竹石亭","f":"七言律诗","c":["卷收湖海入高怀，勘破人閒蛇影杯。","老骨耐看寒后柏，古心相沃渴中梅。","何妨风日同清美，不怕山云碍往来。","多少诗香播牙颊，夕阳移酒坐兰苔。"]},{"t":"次韵竹窗兄委顺斋","f":"七言律诗","c":["知君委顺是心铭，揭以名斋岂浪名。","夜兔晨乌真似梦，秋虫春鸟不关情。","人生未死终归困，天道从来不益盈。","我亦当今知命者，请于此处话平生。"]},{"t":"次韵西山寺主清月","f":"七言律诗","c":["一居西崦一东溟，旷落乾坤本不扃。","古月凄凉惟有梦，清风来往了无形。","翩然好语真心白，中是当年□眼青。","握手笑谈明日事，雪庭庭畔绿杨汀。"]},{"t":"次韵西山寺主僧清月","f":"五言律诗","c":["高占古松閒，尘埃笑却还。","禅机参翠竹，诗价重青山。","长与云分榻，时从鹤出关。","谁云寺门小，穷处足清閒。"]},{"t":"次韵达观弟送法椿长老入杭","f":"五言律诗","c":["与师交际狎，弟后我居前。","久憩上方阁，忽登西浙船。","翩然如过鹤，听不到啼鹃。","心契无千里，诗盟终有缘。"]},{"t":"次韵吴竹修发慈云","f":"五言律诗","c":["入山知几约，手墨未曾乾。","危世一游重，清交百念寒。","吟成佳句易，说到太平难。","终夜饮不醉，何从得睡鼾。"]},{"t":"次韵吴竹修立秋日","f":"七言律诗","c":["白帝来时赤帝归，年年流转不违时。","书镫有约花先喜，庭树无情叶自知。","楸市漫劳兵后梦，莼乡仅免客中思。","老躯便动衣裘想，胠箧其如穴壁儿。"]},{"t":"次韵吴竹修庆余免役","f":"七言律诗","c":["大道荆榛万径斜，中閒役事最堪嗟。","私心自分齐编户，公法仍条存宦家。","免把血躯供刻木，尚存醒眼傲空花。","要知天理无穷处，风雪严时春有涯。"]},{"t":"次韵吴应奎解嘲","f":"七言律诗","c":["两别因循久酿疑，其如老病骨累累。","心铭自勒家庭苦，手绠曾悬坎井危。","吠雪有声非我累，仰天无愧要相知。","交情须看寒松柏，傲尽春风桃李时。"]},{"t":"次韵应诚则次杨君贵来求乃父长卿墓铭","f":"七言律诗","c":["眼中宿草感怀长，听彻啼鹃送洛阳。","萍世生涯随日异，花崖门径尚风光。","心知父志能全我，文得家传早擅场。","天也有人方寸事，本根深处自流芳。"]},{"t":"次韵弟观田蚕即事","f":"五言律诗","c":["诗礼虽传世，农桑不离门。","梅天缫雪屋，秧雨种云村。","衣帛知先老，含饴拟弄孙。","愿言同井乐，无怨亦无恩。"]},{"t":"次韵弟观似单君范","f":"七言律诗","c":["聚忽如萍散忽云，今朝得见满腔春。","诗书有味兵前友，官府无名天下人。","相对两穷消白日，不交一语到红尘。","梅花纸帐寒初试，尽可留连似病身。"]},{"t":"次韵弟观到蔡峰庄","f":"七言律诗","c":["簇簇群山似铁围，中閒著屋与山依。","园多芋栗佐清饮，池足芰荷供隐衣。","畴昔搬家牛自跨，有时见客鹤先飞。","未宜回首林邱旧，剩把诗脾厌翠微。"]},{"t":"次韵弟观咏丹山池荷 其二","f":"七言律诗","c":["一雨西来满寺凉，盈盈不语立方塘。","远公白社所修种，净土青胎无点妆。","要向花光见菩萨，肯从色界问莲香。","回头玉手双杯处，多少风流堕醉乡。"]},{"t":"次韵弟观咏丹山池荷 其一","f":"七言律诗","c":["寺枕丹霞五月凉，藕花数朵碧漪塘。","梵天幻出水云锦，法雨洗空时世妆。","七宝池边分得种，大乘经里喷来香。","是花是色只如是，笑拍阑干何有乡。"]},{"t":"次韵弟观留慈云","f":"五言律诗","c":["相携入翠林，聊尔豁尘襟。","恃熟出家话，得閒生梵心。","凉多却扇坐，困倦把诗吟。","试问虎溪上，多情如此深。"]},{"t":"次韵弟观授学陈子得家","f":"七言律诗","c":["忆昨依依话别端，潇潇暮雨满山寒。","去家幸是老亲健，坐馆当如初宦看。","归梦随风扬绿袂，吟情逐日写诗阑。","从今稳入林深处，涂炭何缘行污冠。"]},{"t":"次韵石秀叔闻莺","f":"七言律诗","c":["分得天机自动簧，与春相约不参商。","无情有态眉如画，是曲非腔口尚黄。","公子旧呼归梦境，友生新好出村庄。","山窗诗客先听处，写入乌丝句亦香。"]},{"t":"次韵弟观雪中二首 其二","f":"七言律诗","c":["万里长天一样云，纷纷吹下玉成尘。","能令下界皆称瑞，谁谓南人不识真。","积冻已多为麦地，培汤更办百花春。","强将光景宽衰老，呵手微吟意欠新。"]},{"t":"次韵弟观雪中二首 其一","f":"七言律诗","c":["剪耳严风利似刀，吹嘘滕六做功劳。","大包天地为一色，老尽山林无二毛。","借煖尚能赊绿蚁，禦寒终不羡裘羔。","天涯多少穷途客，欲寄书难雁影高。"]},{"t":"次韵弟观喜雨二首 其二","f":"七言律诗","c":["世事纷纷付渺茫，且迎雨信看农忙。","鸠声隔树宿云湿，牛影落田新水凉。","处处丛祠群卜稼，家家蓐食早炊粮。","及时种得苗青活，便觉秋风饭粒香。"]},{"t":"次韵弟观喜雨二首 其一","f":"七言律诗","c":["天敕龙瓢到底倾，阿香飞驾会苍冥。","风霆震叠四溟立，宇宙清凉万物醒。","行蚁知几先畏湿，升蜗向上漫遗腥。","平生霖雨苍生志，对景空怀海上亭。"]},{"t":"次韵弟茝怀归","f":"七言律诗","c":["同声相应甚埙篪，雨夜联床只有诗。","断港漫生归棹兴，流年空感浴兰时。","良思难与世情说，衰病聊将僧定移。","须信滞流皆有命，不然安用老天为。"]},{"t":"次韵弟茝客怀","f":"七言律诗","c":["竹洲西畔绿杨阴，一别春光直到今。","老境不生贫富梦，浮云应识去来心。","神明官府颂声满，风月弟兄诗味深。","归办山中□红饭，古来流水一张琴。"]},{"t":"次韵弟茝醉中示弟观二首 其二 为弟茝道","f":"七言律诗","c":["斑发朱颜楚秀翁，陶陶乐意与天融。","凌虚长啸天无际，耐静高眠日过中。","茅屋生涯消几许，梅花气味最相通。","诗书风日何妨共，载得归来自甬东。"]},{"t":"次韵弟茝醉中示弟观二首 其一 自道","f":"七言律诗","c":["六十家婆八十翁，此心无事便融融。","肉香韭甲磁盆内，蝶梦梅花纸帐中。","自有乾坤无俯仰，谁知否泰是穷通。","出门一笑春风阔，孤鹤横天忽自东。"]},{"t":"次韵张子开教授游杖锡寺偶成","f":"七言律诗","c":["禅老慈悲下界愁，长诗招我到深幽。","人知晚节陶元亮，谁识初心马少游。","星月天高空绕鹊，江湖风恶不容鸥。","苦无十亩田堪舍，借得僧房饭几秋。"]},{"t":"次韵张子开喜雨","f":"七言律诗","c":["甘泽连朝拍稻畴，老天著意做今秋。","软炊已报生尘甑，艰食俄忘淅米矛。","圳口涨新浮白腻，禾头濯秀湿青油。","疲农欢喜还长叹，官已催租不待收。"]},{"t":"次韵张子乔来见","f":"五言律诗","c":["人生自多事，本是一蘧庐。","忽忽梦柯外，累累炊剑馀。","清吟投病枕，细读当医书。","此去更何日，相过话索居。"]},{"t":"次韵张子华中秋感时","f":"七言律诗","c":["乾坤万里一长吁，老惫悠悠据槁梧。","未死自惭前死欠，有生不若此生无。","纵闻新诏开途辙，难把陈言入范模。","寄语嵩峰子张子，山林深隐是耆儒。"]},{"t":"次韵杜孟传送归剡","f":"七言律诗","c":["天空地阔本无言，兔走乌飞自做年。","老景光阴炊黍外，客窗风雨酿梅前。","事随笑去户门福，诗为别来朋友贤。","河水洋洋山杳杳，一声归橹绿杨边。"]},{"t":"次韵杨君贵","f":"七言律诗","c":["趁小春晴踏险来，相从溪屋冷生涯。","山林眼力空时态，风月诗声起病怀。","薄酒出篘多亦醉，晚菘入馔淡为佳。","人閒乐处聊示耳，此外本无邱与崖。"]},{"t":"次韵邑丞高洁堂任满来辞","f":"七言律诗","c":["与云游戏佐棠阴，古道谁云不到今。","三载二松公事处，百年乔木世臣心。","夤缘肯及通家旧，饥饿何妨闭户深。","公去那来遗爱在，老犹能听昼帘琴。"]},{"t":"次韵邑宰丁溉之点舟白杜","f":"七言律诗","c":["马首争迎我鲁山，山村风景趁诗还。","樵苏饱暖烟千聚，鸥鹭平安渌几湾。","似把宦荣抛度外，但收民喜上眉间。","作舟事业才轻试，馀刃恢恢心自閒。"]},{"t":"次韵邑宰徐何慊出示所作五首 其五","f":"七言律诗","c":["笠战西风马喷沙，帆樯迎浪舞神鸦。","调舟欲助江流柿，入海非求枣似瓜。","归客迂寻桑社景，吟鞭香带木犀花。","行边好语应听得，秋月春风六万家。"]},{"t":"次韵邑宰徐何慊出示所作五首 其四","f":"七言律诗","c":["锦制丈高底怕伤，手挥烦热坐清凉。","豁开心上平明镜，看破人间戏散场。","县里方将客醉白，台端只怕趣催黄。","梅花本是酸寒物，终累他年铁石肠。"]},{"t":"次韵邑宰徐何慊出示所作五首 其三","f":"七言律诗","c":["嵚崟一岭晓光寒，胸次乾坤本自宽。","高处何妨吞里港，倦时浑欲隐中盘。","攒眉旧市谁安宅，加额残民自拥鞍。","慈父母来千载遇，手将平易扫艰难。"]},{"t":"次韵邑宰徐何慊出示所作五首 其二","f":"七言律诗","c":["谁其知我独春秋，小试毫芒大用留。","二万言书关社稷，八分地位傲公侯。","儒家本色饶青眼，仕路焦心早白头。","笑杀庸人漫多事，包荒襟量自休休。"]},{"t":"次韵邑宰徐何慊出示所作五首 其一","f":"七言律诗","c":["诗是天机不浪吟，自吟自正自规箴。","参成凤诏经纶手，织得麟经笔削心。","宇宙中閒皆分事，云霄高处是知音。","从来老练公名大，两鬓何妨点雪侵。"]},{"t":"次韵里人纾愤","f":"七言律诗","c":["浮生分付四休休，自谓眉閒绝点愁。","鹤在鸡群空有志，鸿罹鱼网莫抽头。","妄灾勿药终须喜，坎难维心底用忧。","荣辱两忘饶落魄，何妨痛饮学巢囚。"]},{"t":"次韵陈晟别瀹","f":"七言律诗","c":["世态悠悠合与分，人生总是一浮云。","瘦□悽恻来东野，妙墨淋漓恍右军。","棠峤别时如梦寐，竹林何日共朝曛。","吾今耄矣虽多感，风月相期未厌闻。"]},{"t":"次韵侄溥偶成","f":"七言律诗","c":["玉藤新月照双明，便觉梅天暑溽轻。","两屋清风交□影，一团和气寿家声。","肯陪醉兴林游畅，更喜骚怀草梦成。","向上路头须努力，席门元不困陈平。"]},{"t":"次韵单君范","f":"七言律诗","c":["驹隙光阴自去留，眉头底用著闲愁。","人生枕上皆槐国，世事棋中几弈秋。","为子孙谋惟蠹简，有风月处即菟裘。","醉多醒语不觉晓，何处钟声出梵楼。"]},{"t":"次韵单君范行李中诸诗前数章自道后二章为单君作也八首 其八","f":"七言律诗","c":["山林气骨本来癯，客气乘时敢阚虚。","韩愈无医惟赠遣，宗元何病岂工书。","不烦天女梵花散，自有乡人傩茢除。","到底群邪须一正，请师孔祷莫踌躇。"]},{"t":"次韵单君范行李中诸诗前数章自道后二章为单君作也八首 其七","f":"七言律诗","c":["浮世憧憧为底忙，百年光景等风狂。","乾坤自隘胸襟豁，言语无多意思长。","但觉高歌同夜酌，未应别赋写春伤。","吾侪渐喜无人识，自做无名草木香。"]},{"t":"次韵单君范行李中诸诗前数章自道后二章为单君作也八首 其六","f":"七言律诗","c":["欲言心事鼻先酸，最怕清流亦倒澜。","尘路争车甘下泽，雪毛满镜自南冠。","高悬古月看时变，相与春风到岁寒。","案有陶诗须细和，无鱼归铗不须弹。"]},{"t":"次韵单君范行李中诸诗前数章自道后二章为单君作也八首 其五","f":"七言律诗","c":["残生光景满腔愁，平地江河汹涌流。","可痛事多周正月，不言心有晋春秋。","俗饕无梦亦寻鹿，人饱自歌谁饭牛。","咄咄向天天不管，方来毕竟几时休。"]},{"t":"次韵单君范行李中诸诗前数章自道后二章为单君作也八首 其四","f":"七言律诗","c":["纷纷万变自鸿荒，人事都归梦一场。","龚胜馀生祇廉里，渊明初意岂柴桑。","山林有味儿亲圃，风雨无眠客对床。","衰老近来诸事废，渔樵唱和是文章。"]},{"t":"次韵单君范行李中诸诗前数章自道后二章为单君作也八首 其三","f":"七言律诗","c":["老不能狂心自箕，览观宇宙百非宜。","沈舟那管帆争水，抱瑟难随竽用时。","祇把书医凭几困，閒从龟决访山疑。","夜来窗下青镫下，兀兀无言渺渺思。"]},{"t":"次韵单君范行李中诸诗前数章自道后二章为单君作也八首 其二","f":"七言律诗","c":["宇宙中閒战血腥，不才难应少微星。","穷顽得寿非三甲，老拙无文况六丁。","醉后时歌东里曲，閒中堪伴北山灵。","门前总是尘埃事，惟有梅花照眼醒。"]},{"t":"次韵单君范行李中诸诗前数章自道后二章为单君作也八首 其一","f":"七言律诗","c":["心如古井不生澜，无奈形骸寄两閒。","老境阳春亦风雪，危时明月自江山。","琴书有旧聊相与，门户虽贫未是閒。","儿女不知何世界，劝传花事已斓斑。"]},{"t":"次韵单景山酴醾","f":"七言律诗","c":["东风先遣百花开，坐后妆梳殢镜台。","雪艳惯逢风落絮，云香不到雨成梅。","下交芍药当阶发，高伴金沙上架来。","珍重美人收拾去，春衣芬馥雅持杯。"]},{"t":"次韵林芳叔夜雨立春二首 其二","f":"五言律诗","c":["官府年头事，山中知未知。","更新夏正朔，依旧汉威仪。","病脚春扶起，归心雨压迟。","东家未吾厌，饱饭细论诗。"]},{"t":"次韵林芳叔夜雨立春二首 其一","f":"五言律诗","c":["今春第一雨，飒飒打窗纱。","莫怪妨镫节，惟忧酿雪花。","报晴俄喜鹊，吠早底嫌蛙。","不自知年耄，随人乐岁华。"]},{"t":"次韵林国器元夕","f":"五言律诗","c":["世情多异好，幻出满城星。","尘市月无色，醉乡风亦腥。","从他儿戏哄，输我客眠醒。","老耳虚鸣处，笙歌足自听。"]},{"t":"次韵竺梅潭老境","f":"五言律诗","c":["浮生年复年，安处即神仙。","子壮閒专日，家和笑答天。","软炊脂白米，甜酿雪清泉。","蔗境有馀味，吟情真造玄。"]},{"t":"次韵范纯甫","f":"七言律诗","c":["与云俱捲出山迟，邂逅初寒旺菊时。","纵欲插花安得笑，无从赊酒若为诗。","乾坤许阔自多碍，风雨又来有故知。","白首犹存旧乌帽，龙山何处渺余思。"]},{"t":"次韵前人为人诬告受羊","f":"七言律诗","c":["冰檗肝肠无诡随，彼嚚何物妄相持。","梦魂不到菜园破，行止肯教芒屩知。","安用舌埋防异日，空闻肉袒有当时。","从他万口自公议，谁学偿金直不疑。"]},{"t":"次韵前人伤古","f":"七言律诗","c":["当年天与裤中儿，天到如今不与时。","事变风涛掀地轴，军声电雹散雷槌。","鬼蓝柄国苦相误，佛会守城甘自痴。","旗盖已随□驾去，留西太乙更谁欺。"]},{"t":"次弟观与雪航韵","f":"七言律诗","c":["老友姑从方外求，危时亦可少纾忧。","笑图难赘馀人契，病室应关一世愁。","淡饭是缘终有味，故山虽好莫回头。","满航雪意元无价，住色空中是应酬。"]},{"t":"次韵前人访旧","f":"七言律诗","c":["铁石心肠本自顽，著身无所奈时艰。","仙丹难问桃花洞，诗笠聊寻饭颗山。","道义岂随天地闭，风埃不放水云閒。","相逢休说如今事，回首斜阳古汉关。"]},{"t":"次韵前人形役","f":"七言律诗","c":["谁能禅寂效裴休，自爱清名慕李舟。","云路中年开辙迹，风波晚岁转船头。","见花如刺时难痛，遇事生根老滞忧。","但欲渔樵相尔汝，怕人知我问来由。"]},{"t":"次韵前人取别二首 其二","f":"七言律诗","c":["云旆吹晴踏翠巅，写成诗卷思翻然。","谁知同赋有齐己，人指醉吟为乐天。","意自源头水中涌，语如山色雨馀鲜。","尾貂分付归鸿去，欲便寻盟未有缘。"]},{"t":"次韵前人取别二首 其一","f":"七言律诗","c":["初心高处欲穷游，兀坐书窗七月秋。","风雨已成贫甫叹，山云却为老韩收。","从来人事有圆缺，可是天公分去留。","正尔无聊负暄立，赤书忽落剡溪头。"]},{"t":"次韵前人贵籴","f":"七言律诗","c":["麦甑凄凉稻尚青，粒珠乘急价掀腾。","市平本易无千斛，仓籴良艰且五升。","长是信天还自活，未能送鬼任多憎。","回头钟鼓群峰寺，饱饭高眠独有僧。"]},{"t":"次韵前人重阳","f":"七言律诗","c":["说道贫閒亦自忙，谁知硕果自存阳。","堪怜冻病如无己，不复狂游似季常。","过眼世情多逐臭，闭门家话自生香。","重阳已在西风里，空有龙山入梦乡。"]},{"t":"次韵前人雪中","f":"七言律诗","c":["晚风吹下六花祥，喜到眉閒色浅黄。","旋积层寒消夙瘴，平施一白洗时妆。","要寻闭户家形迹，肯为乘骓客断肠。","岁事已占禾麦好，与民相庆著诗忙。"]},{"t":"次韵前人寒食","f":"七言律诗","c":["今年寒食倍心寒，不独松楸感涕潸。","青草遥悲新瘗冢，苍梧错认旧来山。","人生醉梦乾坤里，时节晦冥风雨閒。","只有杜鹃知此意，傍云啼去又啼还。"]},{"t":"次韵前人道中","f":"七言律诗","c":["开遍梅花柳渐丝，甘棠次第又添诗。","马头村路皆官况，面上春风是己知。","山笔重时谙事体，蒲鞭轻处惜民饥。","老夫尚解随人后，舞劝碑潭水一卮。"]},{"t":"次韵前人醵更生会三首 其三","f":"七言律诗","c":["世变如轮到厄年，危魂飞绕万山巅。","冥心前路追陶令，回首中原属汉渊。","树鹊频惊枝上月，醯鸡苟活瓮中天。","悠悠未是归时节，风雨何□复对眠。"]},{"t":"次韵前人醵更生会三首 其二","f":"七言律诗","c":["劫火吹炎海水飞，九州同惴釜鱼危。","有时杜老泪盈把，终日颜回面忍饥。","今古滔滔无限事，乾坤纳纳竟何知。","便教强趁黄花约，终恐趑趄罚后期。"]},{"t":"次韵前人醵更生会三首 其一","f":"七言律诗","c":["满天地里暗尘飞，老息奄奄一发危。","种秫为生姑托醉，采薇忍死未忘饥。","三閒书屋鬼神护，百两芒鞋风雨知。","咄咄书空如梦寐，龙山谁记有佳期。"]},{"t":"次韵洛阳秦庆父贽见","f":"五言律诗","c":["洛中人物好，磊磊实过名。","和气春浮动，新诗玉琢成。","相逢交义重，一笑世情轻。","问到牡丹外，凄然百感生。"]},{"t":"次韵洞真道士卢致远","f":"五言律诗","c":["虹桥关福地，门外任风涛。","襟带金钟秀，根基铁柱牢。","安心培大枣，办手摘蟠桃。","坐镇江山稳，新题立石高。"]},{"t":"次韵胡景参制机见寿二首 其二","f":"七言律诗","c":["南风吹笠走长须，一轴新诗一幅书。","虎榜陈人有韩愈，鹤山佳婿得肩吾。","行年八十死将似，求活须臾计已疏。","惭愧珍羞□初度，忽忘门户是穷儒。"]},{"t":"次韵胡景参制机见寿二首 其一","f":"七言律诗","c":["倚囊仙叟付良姻，一实交孚略具文。","共喜树高堪托蔓，自怜莸臭不投薰。","移厨幸免劳都督，问字何妨□子云。","月峡霞峰总奇绝，閒中相望足为群。"]},{"t":"次韵胡甥幼文留别","f":"五言律诗","c":["婿车俄见过，喜气动庭莎。","别久一来重，病馀相问多。","亲情忘淡薄，归兴及清和。","山路须回首，长松有翠萝。"]},{"t":"次韵赵孟益游西山寺","f":"七言律诗","c":["佛何为者占崔嵬，引得骚朋蹈险来。","洗钵有泉披草见，入门无径凿岩开。","避人幽鸟毛生样，守屋残僧面死灰。","自是世閒心绝处，灵山无分莫徘徊。"]},{"t":"次韵赵寄庵","f":"七言律诗","c":["家住黄沙绿水湾，功名土苴任天悭。","顾瞻宇宙惊多碍，收卷江湖憩一閒。","处子声容心自铁，太公年几鬓才斑。","老来难得重相见，明月清风处处山。"]},{"t":"次韵赵菊泉","f":"五言律诗","c":["世衰人物眇，犹见得閒平。","劫火诗书脉，春风杖履盟。","霏霏木屑话，淡淡菜羹情。","相对青镫下，平生心事明。"]},{"t":"次韵赵景文见寄","f":"七言律诗","c":["十载扃门白发翁，一丝飞毒忽缠胸。","浮云随詟惊雷散，跃铁终逃劫火镕。","尚有先庐供手实，幸叨儒籍免身佣。","关津本不征风月，来往何妨信一筇。"]},{"t":"次韵赵景文见寄怀亲","f":"七言律诗","c":["薄俗滔滔逐水流，谁能古道两绸缪。","白云终日静相向，紫气有时来更留。","啼鸟已呼春到了，醉驴曾记旧游不。","山林乐事输君早，未遇仙炊已转头。"]},{"t":"次韵剡张知录见寄","f":"七言律诗","c":["危途盍把隐为师，名姓翻嫌世或知。","栗里已成终老计，桐乡犹记旧游时。","云山杳杳勤搜便，风雨潇潇独寄诗。","目送心期无别语，厚培根本做春枝。"]},{"t":"次韵剡僧孜书记","f":"七言律诗","c":["县如残寺裹荒城，僧干穷缘耐苦声。","虽把慈悲供日用，可能方便徇人情。","四明山背看云近，九里湾头呷水清。","支遁后身偏念我，惠来诗好愧兼荣。"]},{"t":"次韵徐何慊九日登高","f":"七言律诗","c":["广莫亭前秋气清，招邀酒伴走庖兵。","悠然谁解知真意，乐只应须在太平。","直到上峰饶独步，尽收下界入双明。","满头芬馥随归马，惟有黄花不世情。"]},{"t":"次韵徐何慊咏雪","f":"七言律诗","c":["冯夷剪水暗中央，映带同云浅与黄。","旋积层寒消宿瘴，平铺一白洗时妆。","行仙休羡王恭兴，僵叟应关洛令肠。","不觉喜吟丰岁瑞，方知知是为民忙。"]},{"t":"次韵徐直翁仙霞岭近衢州","f":"五言律诗","c":["道大谁能用，功名一念微。","释然文石梦，轻似岫云归。","霞岭空重历，天书的又飞。","翻身凤池去，分阃却成非。"]},{"t":"次韵徐鳞卿","f":"七言律诗","c":["百罹身世不成家，赢得萧萧两鬓华。","梦想山行三载里，绸缪亲谊百年赊。","苍颜一见如枯柏，佳语相延总粲花。","别后有诗须狎寄，莫嫌踏险路谽谺。"]},{"t":"次韵留友直道士来访","f":"五言律诗","c":["九六荡摩中，几人閒处同。","浮生丝傀儡，后计石婆翁。","事事休休过，时时咄咄空。","何如仙羽健，来往傲方蓬。"]},{"t":"次韵翁古晚见寄就送其之京","f":"七言律诗","c":["万里风云路向前，功名盍趁仕强年。","文如李杜谁争燄，心是夷齐不问泉。","别驾有功歌沸海，筑台在望勇趋燕。","自惭筋力难追送，侧耳凌清上集贤。"]},{"t":"次韵翁古晚府判见赠二首 其二","f":"七言律诗","c":["振讯䙰褷病鹤形，箳篂影下话平生。","受原宪业惟环堵，溯德公心不入城。","日把寸量著蝶梦，云拖一出被猿惊。","自惭迂学经题品，输与两生无姓名。"]},{"t":"次韵翁古晚府判见赠二首 其一","f":"七言律诗","c":["清风明月满蓬瀛，谁识监州閒世生。","道义浓香薰政谱，文章馀力到诗城。","傃儒不买三姝媚，好客能容一座惊。","见说锋车春在路，北门西掖是功名。"]},{"t":"次韵崇福老泽南洲","f":"七言律诗","c":["邯郸枕上梦回身，景照窗前醉卧人。","山别是天迟放晚，鸟知何世早呼春。","乾坤大事三缄外，湖海清交一笑新。","山去莫嫌来往密，免教云树两驰神。"]},{"t":"次韵梅山弟","f":"七言律诗","c":["挂画烧香书满前，丰标清出剡溪源。","平坡肘腋眠牛垄，小屋规模放鹤园。","外事任如黄叶寂，閒心暗与白云论。","应须参到希夷处，自是三峰直下孙。"]},{"t":"次韵梅山弟见怀","f":"五言律诗","c":["自笑缘何事，老来还客中。","唱花悲杜牧，隐杵愧梁鸿。","颇忆良眉白，相欢醉面红。","如今各成别，方信坐天穷。"]},{"t":"次韵梅山弟咏梅","f":"七言律诗","c":["冬塞方严春自通，老根芳脉与天融。","清于仙李月梁上，瘦似神苏雪窖中。","庾岭依然开信早，孤山无复课诗工。","一枝在手驿风远，渺渺予怀谁与同。"]},{"t":"次韵梅山弟感时","f":"七言律诗","c":["翳日腥云澒洞尘，是虽天做亦由人。","难禁老泪如囚楚，忍托空言写过秦。","风雪正培阳气脉，山林幸有岁寒身。","功名已付无何有，要及馀光耕富春。"]},{"t":"次韵梅山弟感时四首 其四","f":"七言律诗","c":["边将才无日越晖，中朝人是李斯非。","顺流兵马竟掀舞，死战规模谁发挥。","忍看金茎移露去，空歌玉树送春归。","不图世变今如此，真与尘埃蠓蚋飞。"]},{"t":"次韵梅山弟感时四首 其三","f":"七言律诗","c":["春造曾分寸草晖，晚经霜雪始知非。","中心痛事神孤往，前面虚名手一挥。","肯使晓猿随陇笑，不烦倦鸟引云归。","绝粮只管餐松菊，赢得身轻入险飞。"]},{"t":"次韵梅山弟感时四首 其二","f":"七言律诗","c":["世事滔滔趁夕晖，仰天咄咄付非非。","乾坤谁解中撑拄，江海方听北指挥。","风舞南人新万户，灰飏西岭旧三归。","只应天竺孤峰在，一自飞来不更飞。"]},{"t":"次韵梅山弟感时四首 其一","f":"七言律诗","c":["吟情本是谢玄晖，邂逅年来世事非。","到处望风千甲解，无人留日一戈挥。","杜鹃入洛啼拌死，鸿雁辞南去有归。","浩荡春光天万里，孤云叶叶向谁飞。"]},{"t":"次韵梅山弟感春","f":"七言律诗","c":["老来危迹感秋蓬，万事都归马耳风。","百五节为春好处，两三年在乱离中。","溅花难禁少陵泪，缚柳休辞韩子穷。","最是残镫风雨夜，杜鹃声里梦西东。"]},{"t":"次韵梅山弟静中大观","f":"七言律诗","c":["默默融融内自观，纷纷藉藉外何关。","托言鹏化未为大，相与鸢飞方是閒。","万古乾坤全易上，四时风月小诗閒。","天寒一步不轻动，祇为梅花费往还。"]},{"t":"次韵虚谷和长儿奉别","f":"五言律诗","c":["有便勤相问，何时得近依。","诗搜肠藿瘦，字为眼花肥。","云远心犹远，春归人未归。","羡君牢闭户，珍重白山衣。"]},{"t":"次韵雪窦主同少野见寄","f":"五言律诗","c":["谁肯寄衰翁，当年应梦熊。","知心廑惠远，载酒寿扬雄。","古道今犹在，清交老更丰。","和诗不尽意，极目万山中。"]},{"t":"次韵黄子羽七十自叹","f":"七言律诗","c":["弃瓢巢父固云稀，解印陶潜未是非。","风雨似知人世换，溪山自爱主翁归。","时消孤闷有茶屋，天把独醒存芰衣。","我亦岁寒松下草，相望百里借春晖。"]},{"t":"次韵黄长孺","f":"五言律诗","c":["山谷忽精神，一番桃李新。","杯盘留话处，镫火苟安人。","老去刻为岁，醉来寒亦春。","催归莫閒管，此处岂天津。"]},{"t":"次韵黄长孺","f":"七言律诗","c":["人情相得古来难，肯溯溪山伴退閒。","潇洒风流屏褥外，和平气象瑟琴閒。","鹊巢自爱居南国，鹤帐从教怨北山。","只恐杜鹃声梦里，与君飞去又飞还。"]},{"t":"次韵黄长孺","f":"七言律诗","c":["玉润深惭冰未清，午轩杯酒见人情。","艰难方识山林味，亲戚还兼朋友盟。","安用白头伤世变，又看黄叶报秋成。","羡君燕奉潘舆处，淡泊中閒礼乐声。"]},{"t":"次韵黄长孺别陈子得","f":"五言律诗","c":["两閒何纳纳，长夜正漫漫。","感旧心犹热，逢春眼自寒。","人情伐木宋，世变幻花韩。","寂寞衡茅下，从他作拙看。"]},{"t":"次韵黄虚谷","f":"七言律诗","c":["弓招消息下幽京，群起张弮不受檠。","衰朽分为林下物，英雄谁取彀中名。","坐看年少抟双翼，争把时铦驱五兵。","万事要终方有见，休凭水到说渠成。"]},{"t":"次韵游南山寺","f":"五言律诗","c":["紫盖矗天开，更无山并来。","脚飞云外去，眼到海东回。","长啸落林叶，新题淋壁苔。","兹游亦奇绝，休惜醉徘徊。"]},{"t":"次韵程仲实佥事纪行","f":"七言律诗","c":["道脉来从洛二程，天教驰辔福东瀛。","笔头有海清尘浊，胸次如春放雪晴。","喜拍蓬壶鳌亦抃，攀遮梅驿马难行。","恨无老翼飞随去，岁晚江空潮自生。"]},{"t":"次韵童尚质书怀三首 其三","f":"五言律诗","c":["夜寂气如洗，心閒理自明。","凝香清梦寐，读易悟生平。","月树乌惊晓，云阶鹤报更。","闭门佳致意，名利一毛轻。"]},{"t":"次韵童尚质书怀三首 其二","f":"五言律诗","c":["地偏人迹悄，月到小窗明。","鼓瑟希曾点，观书慨屈平。","物情閒里见，世事梦中更。","不著黄粱枕，虚名已自轻。"]},{"t":"次韵童尚质书怀三首 其一","f":"五言律诗","c":["夜室清如许，檠镫便且明。","哦诗须已断，看剑气难平。","露户浸孤月，江城知几更。","枕书俄作梦，梦觉骨毛轻。"]},{"t":"次韵董三馀约赏月丹瑞香","f":"七言律诗","c":["老仙平日鍊心丹，荏苒光阴百岁閒。","随分种花供冷眼，逢人留酒有温颜。","乾坤只作醒中梦，风月何妨忙处閒。","有约酬春争起舞，要看北道破先悭。"]},{"t":"次韵董伯和二首 其二","f":"七言律诗","c":["时难何必苦嗟吁，自有山庄只自如。","行担应携杏花谱，闭门堪著竹林书。","行观尘外乘风鹤，坐看人閒减水鱼。","宇宙平安终有日，却从旧卜大门闾。"]},{"t":"次韵董伯和二首 其一","f":"七言律诗","c":["事难言处只长吁，沸海烹煎一鼎如。","贫累转添知有命，故交自绝本无书。","仕方见境大槐蚁，走不离乡千里鱼。","已分归农谋半菽，尚忧龙岁起秦闾。"]},{"t":"次韵董伯和镫夕有感二首 其二","f":"七言律诗","c":["数枝镫火古祠门，妆点山中一鬨春。","俚语为求蚕麦福，队游多是布荆人。","强随戏鼓看狂舞，忍听嘶鼙入小颦。","见说九街罗绮地，传呼禁夜令方新。"]},{"t":"次韵董伯和镫夕有感二首 其一","f":"七言律诗","c":["万镫无复艳端门，一簇星毬里域春。","羌调悲酸吹笛社，村声祥瑞卖饧人。","鬼神亦要民心乐，山谷聊舒世态颦。","最好今宵天上月，安知时事有陈新。"]},{"t":"次韵董声可重五","f":"七言律诗","c":["人事俄随世事殊，尚存榴艾伴嘻吁。","怀沙到处哀新鬼，瑞市何时见醉夫。","荣赐休思当暑葛，早衰空感望秋蒲。","辟兵禁恶□儿戏，无计能逃急急符。"]},{"t":"次韵赋南山广莫轩","f":"七言律诗","c":["洗眼来看广莫诗，烟霏空翠雨微微。","四平地上一山起，独拄天南群望归。","乔木不随兵燄动，好云时入寺门飞。","乾坤浩荡难言处，猛拍阑干阁口机。"]},{"t":"次韵龄叟","f":"七言律诗","c":["儒酸自是分当穷，老退非干势不容。","并日莫留馋半菽，馀生休说寿三松。","眼中落落同人少，脚底兢兢坎险重。","惟有灵山老吟友，暗中心事两云龙。"]},{"t":"次韵龄叟见寄","f":"五言律诗","c":["方外好交情，诗筒出醉屏。","清能濯骄暑，光欲掩常星。","自愧薄榆景，有生真草亭。","多年祇多感，岌岌旧门庭。"]},{"t":"次韵龄叟招石秀叔","f":"五言律诗","c":["久知难久别，飞约到柴门。","唤起雨窗困，踏开岚径昏。","世情忙外看，交道淡中存。","何日巳公屋，新诗得共论。"]},{"t":"次韵僧仁泽 其一","f":"五言律诗","c":["来诗自有师，心与晚唐期。","开我正墙面，喜于闻乐脾。","山林人似许，风月事还谁。","不用盟为社，从今是故知。"]},{"t":"次韵僧仁泽 其二","f":"五言律诗","c":["洒洒忘家客，相逢若有期。","茶腴参道味，诗瘦出饥脾。","避俗无新计，谈空更阿谁。","吾言太浪荡，休遣世人知。"]},{"t":"次韵樊伯撝见贶","f":"五言律诗","c":["自笑我何如，叨年八十馀。","户门觉老病，梅竹护穷居。","拙计信天鸟，残生减水鱼。","时将一字命，仰卧向空书。"]},{"t":"次韵戴帅初不赴丹山醵饮二首 其二","f":"七言律诗","c":["危时时节已难得，况得知心盍共杯。","我檄方从风里去，君诗却占日前来。","何须一醉独重九，但是相过多几回。","门外斜阳送行处，眼光飞过碧崔嵬。"]},{"t":"次韵戴帅初不赴丹山醵饮二首 其一","f":"七言律诗","c":["吁嗟世事已难言，得遇重阳强作欢。","白发不供新样眼，黄花却喜旧儒冠。","两三杯里意存古，四十年前盟未寒。","青壁丹崖本深窈，谁知冷处有人看。"]},{"t":"次韵戴帅初以水涨不及赴茂林醵饮重午","f":"七言律诗","c":["回头林谷已云迟，心不怀疑遁自肥。","有菊可寻方觉是，无根自药岂吾非。","危时一醉便为福，好客相过莫放归。","欲吊湘累波浩渺，但须珍重芰荷衣。"]},{"t":"次韵戴帅初见寄","f":"七言律诗","c":["儿造从来自不情，百千万变底人惊。","人生水上浮沤影，物论风前乱叶声。","自笑醉吟空赘传，谁知橘隐竟无名。","况今衰老知何用，惟有关门答五行。"]},{"t":"次韵戴帅初见寄二首 其二","f":"七言律诗","c":["水镜空平取友端，频来山外伴酸寒。","交朋旧在弟兄列，古道新交世俗看。","地近诗筒多便翼，月明心事两危阑。","自家头恼冬烘甚，犹幸偷安未毁冠。"]},{"t":"次韵戴帅初见寄二首 其一","f":"七言律诗","c":["胸次玲珑达事端，入山买屋贮清寒。","奉亲最乐危时见，与俗相忘实处看。","閒辍琴书翻兔册，旋添竹树隔牛阑。","疏衣淡饭门多闭，章甫何妨独旧冠。"]},{"t":"次韵戴帅初赠铜山寺主僧若珣","f":"七言律诗","c":["忆昔曾寻紫翠堆，转头非旧几年来。","僧檐蔓草几成树，佛座莲花半缬苔。","忽自吟边飞锡到，再从空里把山开。","江湖总是风光地，应世因缘第一回。"]},{"t":"次韵戴时芳病中","f":"七言律诗","c":["平生英气欲摩天，晚节逢罹欲自怜。","纸帐漫移春梦枕，画叉难继日支钱。","那知病及穷韩愈，肯把贫谋富计然。","但得身安字堪煮，寄声自有故山鹃。"]},{"t":"次戴帅初与次儿瀹诗","f":"七言律诗","c":["世变纷纷蜂蝶丛，人情落落马牛风。","山林犹喜典刑在，师友相从气义同。","坎有亨心方善处，兑为丽泽要深穷。","暮春乐处儿知否，好趁曾门咏舞童。"]},{"t":"江口偶成","f":"五言律诗","c":["出门何所适，欲见邵云台。","天气晴相送，滩舟小易推。","坐恬时掬水，吟苦恰□梅。","舟子遥相问，江潮来未来。"]},{"t":"竹窗兄因猫捕鸡日囚夜纵有诗自怜因次韵","f":"七言律诗","c":["坎止流行不在人，人生只合任天真。","无聊句践能兴越，垂死范雎终相秦。","病足不妨登上衮，颦眉休复效东邻。","竹窗悟得穷通理，虽致狸奴许自新。"]},{"t":"自金陵趋行都过顾城湖三十里水光接天但风逆不可帆午閒到银林登陆雨作","f":"七言律诗","c":["船路连朝天逆吹，今朝登陆雨相随。","自缘寒素例难阻，非为老苍私控持。","山色青青无世变，梅花皎皎是心知。","眼前有景足消遣，到阙何妨数日迟。"]},{"t":"西渡堰呈孙古岩朝奉","f":"五言律诗","c":["行计又匆匆，投西一短篷。","上河平岸水，暮雨打头风。","得饭已昏后，无眠到夜中。","哦诗欠佳句，为报古岩翁。"]},{"t":"西窗与弟侄戴时芳酌酒","f":"七言律诗","c":["一檐晴色好相陪，可意人能几度来。","便觉酒香随意动，共将书气拓尘开。","有生盍作无生看，未晚何妨到晚回。","安得分时皆是趣，停云归鸟亦悠哉。"]},{"t":"访赵景文不值","f":"七言律诗","c":["见了西山叹复歌，老天元不奈人何。","一身死护松楸活，满眼生来兰玉多。","忍处要如顽铁石，平生能定恶风波。","世閒终有安时节，细把林泉岁月磨。"]},{"t":"过仙山咏孙松涧新庵","f":"七言律诗","c":["雅怀欲友汉刘樊，巧筑屠苏压大兰。","檐宿白云山气重，门无赤日树阴寒。","少年自得老成趣，危世谁如肥遁安。","下界黄尘从扰扰，不妨高枕梦邯郸。"]},{"t":"过崎山","f":"五言律诗","c":["晓过崎山下，溪清水见沙。","石根交虎豹，树影乱龙蛇。","黄竹藏丹渚，青帘卖酒家。","扣舷汀鹭起，撇撇带西斜。"]},{"t":"过鉴湖","f":"七言律诗","c":["越城胜境素来誇，才入东关分外嘉。","八百顷荷西子态，几千馀寺贺君家。","画屏山色饶烟水，丽锦天光落晚霞。","惜景欲图湖上住，钓船泊处是生涯。"]},{"t":"余生日闷中示诸儿","f":"七言律诗","c":["吾今七十有七岁，多事多忧多病馀。","举室忍贫馋煮字，长儿留远梦收书。","券逋积滞泥中兽，户计偷生釜底鱼。","回首当年有今日，苟延如此要何如。"]},{"t":"余自邑归唐溪袁仲素兄弟拉归宿次日苦留连偶病以八句辞","f":"五言律诗","c":["家世厌风波，来居空翠窝。","山深秋意早，溪近夜声多。","似梦忽到此，欲留如病何。","眼前浑是趣，未得细吟哦。"]},{"t":"余床帐为过兵捲去答梅山弟用余韵见寄","f":"七言律诗","c":["一床破帐护衰翁，席捲俄随掠骑东。","与妇同围肤炭火，呼儿排作肉屏风。","从来不起羊羔想，困倒何妨蝶梦通。","乱世流离多露宿，盖头有屋未为空。"]},{"t":"别龄叟八句","f":"七言律诗","c":["翠竹黄花曲曲香，中间犹有太平腔。","淡交一饭云山钵，诗梦对床风雨窗。","忽动归心随晚策，尚留醉兴寄春缸。","閒行除却禅关外，牢闭柴门学老庞。"]},{"t":"即事","f":"五言律诗","c":["新正已强半，连阴凝不开。","雨声严似雪，春色瘦于梅。","老不问花事，病犹须酒杯。","东风自时样，于我亦悠哉。"]},{"t":"即事","f":"五言律诗","c":["出门问春事，犹在可疑閒。","云弄欲晴日，风坚曾雪山。","千林芳信远，百鸟好声悭。","要识天珍重，时光渐渐还。"]},{"t":"君贵用前韵来谢又次韵答之","f":"七言律诗","c":["青鞋踏过剡山长，黄菊初香替紫阳。","情话绸缪无世变，意吟潇洒似秋光。","别来杏苑惊三载，问及花崖梦一场。","我亦风前霜后叶，饶君青发擅春芳。"]},{"t":"吴江县作","f":"七言律诗","c":["不行浙右已三年，却上今秋考试船。","文禁何妨鸥鹭狎，厨供旋得蟹鱼鲜。","远山浮动太湖浪，密树冥濛小市烟。","及过长桥风正恶，倚船无语看青天。"]},{"t":"吴竹修以诗寄次韵以复","f":"七言律诗","c":["避世归来星一周，小丹山下剡溪头。","风尘满眼醒如醉，宇宙关心笑亦愁。","书几日听诸子业，菜畦时共老妻游。","吟鞭倘践相过约，鸡黍犹能食仲由。"]},{"t":"吴宜之生日以一诗勉之","f":"七言律诗","c":["伍山钟秀出人龙，头角峥嵘意气雄。","须著父兄深责望，好从师友细磨砻。","始勤却是终身福，下学方收上达功。","它日前程相约处，杏园多少马头风。"]},{"t":"呈月窗兄","f":"五言律诗","c":["颇有爱山心，山人交未深。","不知回俗驾，依旧入儒林。","乐处外何有，故书中可寻。","渔蓑归得晚，风雨伴吾吟。"]},{"t":"呈雪窦僧野翁","f":"五言律诗","c":["雨屋又留连，回头七载前。","同游半黄土，百感两霜颠。","睡醒茶为祟，吟清山结缘。","他年北窗下，谁复对床眠。"]},{"t":"呈龄叟","f":"七言律诗","c":["寥寥古道独开门，一见无言心已闻。","别后黄尘留四月，坐来清雨洗三分。","鳞鳞秧活方吞水，翼翼山飞欲舞云。","此景此生如此酒，證明耐久有南薰。"]},{"t":"寿同父兄七十二首 其二","f":"七言律诗","c":["吾家兄弟笃天伦，晚景怡怡仅两人。","门户相依杏阴旧，藩篱不隔棣华春。","难逢燕夜如今日，回愧鳞年以次身。","造物倘容顽健在，愿为老栎伴庄椿。"]},{"t":"寿同父兄七十二首 其一","f":"七言律诗","c":["光风颜色雪髯鲜，已到人閒稀有年。","心好共称生下佛，身闲自谓饮中仙。","安贫真味齐眉馈，养善良方高枕眠。","更看镫宵儿迎妇，一家春与月团圆。"]},{"t":"寿吴景年","f":"七言律诗","c":["托迹红尘不染尘，径梅溪竹共精神。","字真正逼张居士，禅味曾参印上人。","声色素轻非为老，须眉虽皓却如新。","儿孙须得文章力，富贵丛中一寿椿。"]},{"t":"寿法椿长老二首 其二","f":"七言律诗","c":["一相从后便相知，结得因缘似许奇。","如水笑谈多尽日，与云来往本无时。","为莲社约非吾事，读藕花诗欲汝师。","熟处不妨安稳住，江湖风浪更交谁。"]},{"t":"寿法椿长老二首 其一","f":"七言律诗","c":["慈云一坐十年过，耐受空门末劫魔。","晨粥应缘千里到，秋粮入供寸功磨。","当风松干神弥爽，经雪梅花韵更多。","大地山河供一笑，底须天女问云何。"]},{"t":"寿炳同长老","f":"七言律诗","c":["飞雪亭边欲雪天，当年生日又今年。","云山卓锡闲心外，湖海烧香笑面前。","每为寒交倾钵施，更多雅客问诗禅。","最高高处长长寿，赞叹中閒欢喜缘。"]},{"t":"弟观喜董稼山至有诗因次韵二首 其二","f":"七言律诗","c":["误辱高轩访子云，须知我自是玄真。","石心已落千寻海，霜鬓难留一发春。","门外道途新旧眼，兵前朋友死生身。","如今聚首休轻别，他日黄金枉铸人。"]},{"t":"弟观喜董稼山至有诗因次韵二首 其一","f":"七言律诗","c":["苍狗白衣纷过云，到头故我始为真。","山林高看平沈世，风雨难摧独乐春。","时出苦言医俗耳，多培好事寿閒身。","仰天咄咄今何日，百里相过有若人。"]},{"t":"张氏馆中早作","f":"七言律诗","c":["小窗一榻清于水，亲戚相看话久暌。","困带诗情投角枕，梦随梅伴策霜藜。","邻家落杵催樵爨，山寺分钟撼竹栖。","犯冷披衣捲帘立，小丹山在翠楼西。"]},{"t":"张敬之县尉","f":"五言律诗","c":["仙棹发秋湾，稽山到不难。","要将培远业，便答自初官。","秦望一峰峭，贺湖千顷宽。","用心行己处，时向此中看。"]},{"t":"杖锡山别前人","f":"七言律诗","c":["结约登临百里深，流连风雨一窗阴。","新寒镫火照清梦，绝静山林生古音。","此日与君相别处，有天知我不言心。","归途步步须回首，苍壁擎云几万寻。"]},{"t":"杜工部诗有送弟观归蓝田迎新妇二首偶与县尉弟达观同名娶事又同因韵戏示 其二","f":"五言律诗","c":["扇手笑终在，琴心曲暗留。","相期星户夕，莫负月娥秋。","金濑迟扬旆，蓝桥趣问舟。","定将先入梦，骖凤绕箫楼。"]}]};